function wrapSectionLabels(el) {
    el.innerHTML = el.innerHTML.replace(
        /\[([^\]]+:)\]/g,
        '<span class="tt-section-label">$1</span>'
    );
}

function applyCompactBrs(el) {
    // Read [br]-marked labels from the template definition (not from AI output).
    // Ensures the label span ends with a <br> so the line break is hidden
    // together with the label. If the AI put content on the same line
    // (no BR sibling), we insert one inside the span ourselves.
    const template = window._flowTextTemplate || '';
    const compactLabels = new Set();
    const re = /\[([^\]]+:)\]\[br\]/g;
    let m;
    while ((m = re.exec(template)) !== null) compactLabels.add(m[1].trim());
    if (!compactLabels.size) return;
    el.querySelectorAll('.tt-section-label').forEach(span => {
        if (compactLabels.has(span.textContent.trim())) {
            const next = span.nextSibling;
            if (next?.nodeName === 'BR') {
                span.appendChild(next); // move existing BR inside
            } else {
                span.appendChild(el.ownerDocument.createElement('br')); // insert BR inside
            }
        }
    });
}

function applyLabelVisibility() {
    const labels = ttContent.querySelectorAll('.tt-section-label');
    labels.forEach(s => { s.style.display = _ttLabelsVisible ? '' : 'none'; });
    ttToggleLabels.textContent = _ttLabelsVisible ? 'Labels verbergen' : 'Labels tonen';
    ttToggleLabels.classList.toggle('bg-cyan-50', !_ttLabelsVisible);
    ttToggleLabels.classList.toggle('dark:bg-cyan-900/30', !_ttLabelsVisible);
    ttToggleLabels.classList.toggle('border-cyan-300', !_ttLabelsVisible);
    ttToggleLabels.classList.toggle('dark:border-cyan-700', !_ttLabelsVisible);
}

ttToggleLabels.addEventListener('click', () => {
    _ttLabelsVisible = !_ttLabelsVisible;
    applyLabelVisibility();
});

