    targetStatus.innerHTML = '<span class="autofill-spinner"></span> Verwerken…';
    targetContent.innerHTML = '';

    _ttAbort?.abort();
    _ttAbort = new AbortController();

    let firstChunk = true;
    try {
        // Phase 1: generate filled backup template
        await callGeminiStream(getModel('geminiModelAutofillBackup'), backupPrompt, (partial) => {
            if (firstChunk) { firstChunk = false; targetStatus.innerHTML = ''; }
            targetContent.innerHTML = renderMarkdown(partial);
        }, _ttAbort.signal);

        // Save the backup result for the toggle (↩ Ingevuld)
        const backupPlainText = targetContent.innerText;
        if (isMain) _ttOriginalText = backupPlainText;
        else pipRefs.origText = backupPlainText;

        // Phase 2: run verslag check (skipped when vcAfterAutofillEnabled is off)
        if (vcAfterAutofillEnabled) {
            targetStatus.innerHTML = '<span class="autofill-spinner"></span> Verslag check…';
            const vcTemplate = verslagCheckUrlInput.value.trim() || DEFAULT_VERSLAG_CHECK_PROMPT;
            const vcPrompt = fillPrompt(vcTemplate, {
                tekst: backupPlainText,
                type_onderzoek: typeOnderzoek,
                klinische_inlichtingen: ki,
                diagnostische_vraagstelling: dv,
                patient_info: extractPatientInfo(),
                text_template: window._flowTextTemplate || '',
            });
            firstChunk = true;
            await callGeminiStream(getModel('geminiModelVerslag'), vcPrompt, (partial) => {
                if (firstChunk) { firstChunk = false; targetStatus.innerHTML = ''; }
                targetContent.innerHTML = renderMarkdown(partial);
            }, _ttAbort.signal);
        }

        targetStatus.innerHTML = '';
        targetActions.style.display = 'flex';
        // Only show Toon origineel when verslag check ran (two versions to compare)
        targetToggle.style.display = (vcAfterAutofillEnabled && backupPlainText) ? 'inline-flex' : 'none';
        // Wrap [Label:] patterns and show toggle button if any labels are present.
        // Use backupPlainText (phase 1 output) to detect labels so the button shows
        // even when the verslag check (phase 2) strips them from the final output.
        const hasLabels = /\[[^\]]+:\]/.test(backupPlainText);
        if (isMain) {
            _ttLabelsVisible = window._flowLabelsDefaultVisible !== false;
            wrapSectionLabels(ttContent);
            applyCompactBrs(ttContent);
            ttToggleLabels.style.display = hasLabels ? '' : 'none';
            ttToggleLabels.classList.remove('hidden');
            applyLabelVisibility();
        } else if (pipRefs?.labelsBtn) {
            pipRefs.labelsVisible = window._flowLabelsDefaultVisible !== false;
            wrapSectionLabels(targetContent);
            applyCompactBrs(targetContent);
            pipRefs.labelsBtn.style.display = hasLabels ? '' : 'none';
            pipRefs.applyLabels();
        }
    } catch (e) {
        targetStatus.innerHTML = '';
        if (e.name !== 'AbortError') targetContent.innerHTML = '<span class="text-red-500">Fout: ' + e.message + '</span>';
    }
}

