function renderMarkdown(rawText) {
    const corrSpan = (orig, corr) => hoveringMode
        ? `<span class="corr" style="color:#ef4444;font-weight:bold;font-style:italic" data-orig="${orig.replace(/"/g,'&quot;')}">${corr}</span>`
        : `<span style="color:#ef4444;font-weight:bold;font-style:italic">${corr}</span>`;

    // Strip markdown code fences (models sometimes wrap output in ```lang...```)
    let text = rawText.trim()
        .replace(/^```[^\n]*\n?/, '')
        .replace(/\n?```\s*$/, '');
    // Unescape HTML entities (some models return &lt;del&gt; instead of <del>)
    text = text
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&amp;/g, '&');

    // Convert markdown tables before newline→<br> conversion
    text = text.replace(/((?:^|\n)(?:\|[^\n]+\|\n?){2,})/g, (block) => {
        const lines = block.trim().split('\n').filter(l => /^\|/.test(l.trim()));
        const sepIdx = lines.findIndex(l => /^\|[\s|:-]+\|$/.test(l.trim()));
        if (sepIdx < 1) return block;
        const parseRow = l => l.split('|').slice(1, -1).map(c => c.trim());
        const hdr = parseRow(lines[sepIdx - 1]).map(c => `<th style="border:1px solid var(--tw-border);padding:3px 8px;background:var(--th-bg);text-align:left;font-size:0.75rem;font-weight:600">${c}</th>`).join('');
        const rows = lines.slice(sepIdx + 1).map(l =>
            '<tr>' + parseRow(l).map(c => `<td style="border:1px solid var(--tw-border);padding:3px 8px;font-size:0.75rem">${c}</td>`).join('') + '</tr>'
        ).join('');
        return `\n<table style="border-collapse:collapse;width:100%;margin:4px 0"><thead><tr>${hdr}</tr></thead><tbody>${rows}</tbody></table>\n`;
    });

    // Whitelist and convert known safe HTML tags, strip the rest
    const html = text
        // Primary format: <del>original</del><ins>correction</ins> — explicit, reliable
        .replace(/<del>(.*?)<\/del>\s*<ins>(.*?)<\/ins>/gis,
            (_, orig, corr) => corrSpan(orig.trim(), corr.trim()))
        // Backwards compat: old title-attribute format
        .replace(/<b>\s*<i>\s*<font\s+color=['"]red['"]\s+title=['"]([^'"]+)['"]\s*>(.*?)<\/font>\s*<\/i>\s*<\/b>/gis,
            (_, orig, corr) => corrSpan(orig, corr))
        .replace(/<font\s+color=['"]red['"]\s+title=['"]([^'"]+)['"]\s*>(.*?)<\/font>/gis,
            (_, orig, corr) => corrSpan(orig, corr))
        // Backwards compat: old no-title format
        .replace(/<b>\s*<i>\s*<font\s+color=['"]red['"]\s*>(.*?)<\/font>\s*<\/i>\s*<\/b>/gis,
            (_, corr) => corrSpan('', corr))
        .replace(/<font\s+color=['"]red['"]\s*>(.*?)<\/font>/gis,
            (_, corr) => corrSpan('', corr))
        .replace(/<b>(.*?)<\/b>/gis,      '<strong>$1</strong>')
        .replace(/<strong>(.*?)<\/strong>/gis, '<strong>$1</strong>')
        .replace(/<i>(.*?)<\/i>/gis,      '<em>$1</em>')
        .replace(/<em>(.*?)<\/em>/gis,    '<em>$1</em>')
        // Markdown fallback
        .replace(/^#{1,3}\s+(.+)$/gm,    '<strong>$1</strong>')
        .replace(/\*\*\*(.*?)\*\*\*/gs, '<span style="color:#ef4444;font-weight:bold;font-style:italic">$1</span>')
        .replace(/\*\*(.*?)\*\*/gs,      '<strong>$1</strong>')
        .replace(/\*(.*?)\*/gs,           '<em>$1</em>')
        // Markdown links [text](https://...) → clickable anchor
        .replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,
            '<a href="$2" target="_blank" rel="noopener noreferrer" style="color:#0891b2;text-decoration:underline">$1</a>')
        // Strip any remaining unknown tags (allow table, a, tr, td, th elements)
        .replace(/<(?!\/?(strong|em|span|br|a|table|thead|tbody|tr|td|th)\b)[^>]+>/gi, '')
        .replace(/\n/g, '<br>');
    return html;
}

