function renderTemplatePreviewHtml(text) {
    return text.split('\n').map(line => {
        const ci = line.indexOf('//');
        const visible = ci >= 0 ? line.slice(0, ci).trimEnd() : line;
        let e = visible
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
        e = e.replace(/XXX|\{[^}]*\}|\[[^\]]*\]|'[^']*'|"[^"]*"/g, m => {
            if (m === 'XXX')  return '<span style="color:#f472b6">XXX</span>';
            if (m[0] === '{') return '<span style="color:#fb923c">' + m + '</span>';
            if (m[0] === '[') return '<span style="color:#38bdf8">' + m + '</span>';
            return '<span style="color:#fbbf24">' + m + '</span>';
        });
        return e;
    }).join('\n');
}

