document.getElementById('save-edit-btn').addEventListener('click', () => {
    // Flush any pending AI rule edits
    document.getElementById('ai-rules-list').querySelectorAll('.ai-rule').forEach(row => {
        const i = +row.dataset.i;
        if (!editAiRules[i]) return;
        editAiRules[i].aiSource  = row.querySelector('.ai-src').value;
        editAiRules[i].condition = { operator: row.querySelector('.ai-op').value, value: row.querySelector('.ai-val').value };
        editAiRules[i].action    = row.querySelector('.ai-act').value;
        editAiRules[i].template  = row.querySelector('.ai-tpl').value;
    });

    // Flush any pending calculator edits and drop empty rows
    document.getElementById('calculators-list').querySelectorAll('.calc-row').forEach(row => {
        const i = +row.dataset.i;
        if (!editCalculators[i]) return;
        editCalculators[i].calcId = row.querySelector('.calc-id').value;
        editCalculators[i].tiroTemplateUrl = row.querySelector('.calc-tpl').value.trim();
    });
    editCalculators = editCalculators.filter(c => c.calcId);

    const name = document.getElementById('edit-name').value.trim();
    if (!name) { alert('Naam is verplicht.'); return; }
    const replaceCount = editAiRules.filter(r => r.action === 'replace_template' && r.template).length;
    if (replaceCount > 1) { alert('Er kan maximaal één AI-regel zijn met de actie "Vervang template". Pas de regels aan.'); return; }

    const _existingForSave = state.examTypes.find(t => t.id === currentEditId);
    const updated = {
        id:           currentEditId === '__new__' ? ('et-' + Date.now()) : currentEditId,
        name,
        code:         document.getElementById('edit-code').value.trim(),
        modality:     document.getElementById('edit-modality').value,
        dicom:        [...editDicomList],
        deptTemplate:  document.getElementById('edit-dept-template').value.trim(),
        userTemplate:  document.getElementById('edit-user-template').value.trim(),
        textTemplate:  document.getElementById('edit-text-template').value.trim(),
        presetText:    document.getElementById('edit-preset-text').value.trim(),
        aiRules:       editAiRules,
        calculators:   editCalculators,
        labelsDefaultVisible: _existingForSave?.labelsDefaultVisible === true,
    };

    if (currentEditId === '__new__') {
        state.examTypes.push(updated);
    } else {
        const idx = state.examTypes.findIndex(t => t.id === currentEditId);
        if (idx >= 0) state.examTypes[idx] = updated;
    }
    saveData();
    closeSlideOver();
    renderCards();
});

document.getElementById('delete-btn').addEventListener('click', () => {
    if (!confirm(`"${state.examTypes.find(t=>t.id===currentEditId)?.name}" verwijderen?`)) return;
    state.examTypes = state.examTypes.filter(t => t.id !== currentEditId);
    saveData();
    closeSlideOver();
    renderCards();
});

