        function renderAiRules() {
            const el = document.getElementById('ai-rules-list');
            if (!editAiRules.length) {
                el.innerHTML = `<p class="text-xs text-neutral-400 dark:text-neutral-500 italic py-1">Geen AI-regels ingesteld.</p>`;
                return;
            }
            // Only one rule may have action="replace_template"
            const replaceIdx = editAiRules.findIndex(r => r.action === 'replace_template');
            el.innerHTML = editAiRules.map((r, i) => {
                const replaceDisabled = replaceIdx !== -1 && replaceIdx !== i;
                return `
<div class="ai-rule border border-neutral-200 dark:border-slate-700 rounded-lg p-3 space-y-2 bg-neutral-50/60 dark:bg-[#161f27]/50" data-i="${i}">
  <div class="flex items-center justify-between">
    <span class="text-[10px] font-bold uppercase tracking-wide text-amber-600 dark:text-amber-500">Regel ${i+1}</span>
    <button type="button" class="rm-rule text-[11px] text-red-500 hover:text-red-600 hover:underline" data-i="${i}">Verwijder</button>
  </div>
  <div class="grid grid-cols-2 gap-2">
    <div>
      <label class="block text-[10px] uppercase tracking-wide text-neutral-400 mb-1">AI bron / model</label>
      <input type="text" class="ai-src w-full text-xs font-mono rounded border border-neutral-300 dark:border-slate-700 px-2 py-1.5 focus:outline-none focus:ring-1 focus:ring-cyan-500" placeholder="fracture_detection" value="${esc(r.aiSource||'')}" data-i="${i}">
    </div>
    <div>
      <label class="block text-[10px] uppercase tracking-wide text-neutral-400 mb-1">Conditie</label>
      <select class="ai-op w-full text-xs rounded border border-neutral-300 dark:border-slate-700 px-2 py-1.5 focus:outline-none focus:ring-1 focus:ring-cyan-500" data-i="${i}">
        ${AI_OPS.map(op => `<option value="${op.v}" ${(r.condition?.operator||'equals')===op.v?'selected':''}>${op.l}</option>`).join('')}
      </select>
    </div>
  </div>
  <div class="grid grid-cols-2 gap-2">
    <div>
      <label class="block text-[10px] uppercase tracking-wide text-neutral-400 mb-1">Waarde</label>
      <input type="text" class="ai-val w-full text-xs rounded border border-neutral-300 dark:border-slate-700 px-2 py-1.5 focus:outline-none focus:ring-1 focus:ring-cyan-500" placeholder="positive / 0.8 / …" value="${esc(r.condition?.value||'')}" data-i="${i}">
    </div>
    <div>
      <label class="block text-[10px] uppercase tracking-wide text-neutral-400 mb-1">Actie</label>
      <select class="ai-act w-full text-xs rounded border border-neutral-300 dark:border-slate-700 px-2 py-1.5 focus:outline-none focus:ring-1 focus:ring-cyan-500" data-i="${i}">
        <option value="replace_template" ${r.action==='replace_template'?'selected':''} ${replaceDisabled?'disabled':''}>Vervang template${replaceDisabled?' (al in gebruik)':''}</option>
        <option value="add_template"     ${r.action==='add_template'?'selected':''}>Voeg template toe</option>
      </select>
    </div>
  </div>
  <div>
    <label class="block text-[10px] uppercase tracking-wide text-neutral-400 mb-1">Template URL</label>
    <input type="text" class="ai-tpl w-full text-xs font-mono rounded border border-neutral-300 dark:border-slate-700 px-2 py-1.5 focus:outline-none focus:ring-1 focus:ring-cyan-500" placeholder="tiro://templates/…" value="${esc(r.template||'')}" data-i="${i}">
  </div>
</div>`;
            }).join('');

            el.querySelectorAll('.rm-rule').forEach(btn =>
                btn.addEventListener('click', () => {
                    editAiRules.splice(+btn.dataset.i, 1);
                    renderAiRules();
                })
            );

            function syncAll() {
                el.querySelectorAll('.ai-rule').forEach(row => {
                    const i = +row.dataset.i;
                    if (!editAiRules[i]) return;
                    editAiRules[i].aiSource   = row.querySelector('.ai-src').value;
                    editAiRules[i].condition  = { operator: row.querySelector('.ai-op').value, value: row.querySelector('.ai-val').value };
                    editAiRules[i].action     = row.querySelector('.ai-act').value;
                    editAiRules[i].template   = row.querySelector('.ai-tpl').value;
                });
            }

            el.querySelectorAll('input, select').forEach(inp =>
                inp.addEventListener('input', syncAll)
            );
        }

        document.getElementById('add-ai-rule-btn').addEventListener('click', () => {
            const replaceExists = editAiRules.some(r => r.action === 'replace_template');
            editAiRules.push({ aiSource:'', condition:{ operator:'positive', value:'' }, action: replaceExists ? 'add_template' : 'replace_template', template:'' });
            renderAiRules();
