const mkSendBtn = (getTextFn) => {
    const b = mkBtn('inline-flex items-center justify-center w-[28px] h-[28px] rounded-md border border-neutral-300 dark:border-slate-700 bg-white dark:bg-muted hover:bg-neutral-200 dark:hover:bg-slate-600 text-neutral-700 dark:text-neutral-200 transition-colors cursor-pointer flex-shrink-0', '', () => {
        const text = getTextFn();
        if (!text || !text.trim()) return;
        setNativeValue(ta, text);
        _autoGrow();
        setDictationText(text);
    });
    b.title = 'Stuur naar DMO dicteerveld';
    b.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="19" x2="12" y2="5"/><polyline points="5 12 12 5 19 12"/></svg>';
    return b;
};

// Copy plain text inside the PiP window using execCommand (clipboard API unavailable in PiP)
function pipCopy(text) {
    // Prefer modern Clipboard API (runs in main-window context, so navigator refers to main window)
    if (navigator.clipboard?.writeText) {
        navigator.clipboard.writeText(text).catch(() => _pipCopyFallback(text));
    } else {
        _pipCopyFallback(text);
    }
}
function _pipCopyFallback(text) {
    try {
        const el = pipWindow.document.createElement('textarea');
        el.value = text;
        el.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0;pointer-events:none';
        pipWindow.document.body.appendChild(el);
        el.focus(); el.select();
        pipWindow.document.execCommand('copy');
        pipWindow.document.body.removeChild(el);
    } catch(e) {}
}

