function renderFlowCheckboxItem(name, label, checked, mode, calcId) {
    const v = name.replace(/"/g, "&quot;");
    const l = label.replace(/</g, "&lt;").replace(/>/g, "&gt;");
    const isTextueel = mode === 'textueel';
    const isCalc = mode === 'calculator';
    let textColor = 'text-neutral-700 dark:text-neutral-300';
    let checkboxColor = 'text-cyan-600 focus:ring-cyan-500';
    let dataAttr = '';
    let prefix = '';
    if (isTextueel) {
        textColor = 'text-amber-700 dark:text-amber-400';
        checkboxColor = 'accent-amber-500';
        dataAttr = ' data-mode="textueel"';
    } else if (isCalc) {
        textColor = 'text-cyan-700 dark:text-cyan-400';
        checkboxColor = 'accent-cyan-600';
        dataAttr = ` data-mode="calculator" data-calc-id="${(calcId||'').replace(/"/g,'&quot;')}"`;
        prefix = '🧮 ';
    }
    return `<label class="flex items-center gap-2 text-sm ${textColor} cursor-pointer">
        <input type="checkbox" class="template-checkbox w-4 h-4 rounded border-neutral-300 dark:border-slate-700 ${checkboxColor}" value="${v}"${checked ? " checked" : ""}${dataAttr}>
        ${prefix}${l}
    </label>`;
}

function setDynamicTemplates(items) {
    // Store calculator info keyed by checkbox value
    window._flowCalculators = {};
    items.forEach(t => {
        if (t.mode === 'calculator' && t.calcId) {
            window._flowCalculators[t.name] = { calcId: t.calcId, tiroTemplateUrl: t.tiroTemplateUrl || '', naam: t.label || t.calcId };
        }
    });
    // Flow-templates in #dynamic-templates (boven de lijn); calculatoren in #calc-templates (onder "AI en Calculatoren")
    const tplItems  = items.filter(t => t.mode !== 'calculator');
    const calcItems = items.filter(t => t.mode === 'calculator');
    document.getElementById("dynamic-templates").innerHTML =
        tplItems.map(t => renderFlowCheckboxItem(t.name, t.label || t.name, !!t.checked, t.mode, t.calcId)).join("");
    const calcEl = document.getElementById("calc-templates");
    if (calcEl) calcEl.innerHTML =
        calcItems.map(t => renderFlowCheckboxItem(t.name, t.label || t.name, !!t.checked, t.mode, t.calcId)).join("");
    updateActiveTemplateSuffix();
    if (typeof renderCalcPicker === 'function') renderCalcPicker();
}

