function applyFlowMatch(match) {
    showFlowStatus(null);
    const items = [];

    // Priority logic:
    // - gebruiker replaces afdeling (afdeling unchecked when gebruiker exists)
    // - first AI replace_template unchecks gebruiker and is checked instead
    // - additional AI add_template rules are always checked (stack on top)
    const aiRules = match.aiRules || [];
    const hasReplaceAI = aiRules.some(r => r.action === 'replace_template' && r.template);
    const hasUser = !!match.userTemplate;

    const deptTextActive = match.deptMode === 'textueel';
    const userTextActive = match.userMode === 'textueel';
    if (match.deptTemplate) {
        const key = "flow:dept:" + match.id;
        TEMPLATES[key] = match.deptTemplate;
        items.push({ name: key, label: match.name + " - afdeling", checked: !deptTextActive && !hasUser && !hasReplaceAI });
    }
    if (match.userTemplate) {
        const key = "flow:user:" + match.id;
        TEMPLATES[key] = match.userTemplate;
        items.push({ name: key, label: match.name + " - gebruiker", checked: !userTextActive && !hasReplaceAI });
    }
    let replaceUsed = false;
    aiRules.forEach((rule, i) => {
        if (!rule.template) return;
        const key = "flow:ai:" + match.id + ":" + i;
        TEMPLATES[key] = rule.template;
        const isReplace = rule.action === 'replace_template';
        const checked = isReplace ? !replaceUsed : true;
        if (isReplace) replaceUsed = true;
        const suffix = isReplace ? ' (vervangen)' : ' (toevoegen)';
        items.push({ name: key, label: match.name + " - AI" + suffix, checked });
    });

    // ── Calculatoren ──────────────────────────────────────────────────
    const calcs = match.calculators || [];
    const RC = (window.RADCALC && window.RADCALC.byId) ? window.RADCALC : null;
    calcs.forEach(c => {
        if (!c.calcId) return;
        const def = RC ? RC.byId(c.calcId) : null;
        const naam = def ? def.naam : c.calcId;
        const key = `flow:calc:${match.id}:${c.calcId}`;
        TEMPLATES[key] = '__calculator__';
        items.push({ name: key, label: naam, checked: false, mode: 'calculator', calcId: c.calcId, tiroTemplateUrl: c.tiroTemplateUrl || '' });
    });

    // Store text template from flow match for use in AI prompts and backup display
    window._flowTextTemplate = match.textTemplate || '';
    window._flowUserTextTemplate = match.userTextTemplate || '';
    window._flowPresetText = match.presetText || '';
    window._flowLabelsDefaultVisible = match.labelsDefaultVisible === true;
    window._flowTextTemplateLogic = '';
    try {
        window._flowTextTemplateLogic = localStorage.getItem('textTemplateLogic') || '';
    } catch(_) {}

    if (items.length === 0) {
        if (window._flowTextTemplate || window._flowUserTextTemplate) {
            showFlowStatus("Onderzoekstype gevonden — textuele template actief", true);
            setDynamicTemplates([]);
        } else {
            showFlowStatus("Onderzoekstype gevonden maar nog geen templates ingesteld");
            setDynamicTemplates(DEFAULT_FLOW_TEMPLATES);
        }

