function createTemplateForms() {
    const selected = Array.from(document.querySelectorAll(".template-checkbox:checked")).map(cb => cb.value);
    // Don't persist flow: keys — they're rebuilt from flow config on each context update
    localStorage.setItem("savedTemplateNames", JSON.stringify(selected.filter(n => !n.startsWith("flow:"))));

    const container = document.getElementById("template-forms-container");
    container.innerHTML = "";
    form = null;
    latestReportQuestionnaire = null; // reset when templates change

    selected.forEach((name, index) => {
        const url = TEMPLATES[name];
        if (!url || url === '__calculator__') return; // calculator entries have no Tiro form

        const updatedParamResource = {
            ...paramResource,
            parameter: [
                ...paramResource.parameter.filter(p => p.name !== "questionnaire"),
                { name: "questionnaire", valueString: url },
            ],
        };
        const updatedLaunchContext = { ...launchContext, custom: updatedParamResource };

        const ff = document.createElement("tiro-form-filler");
        ff.setAttribute("sdc-endpoint-address", "https://sdc.tiro.health/fhir/r5");

