input.new_string:
document.getElementById("template-checkboxes").addEventListener("change", (e) => {
    if (e.target.matches(".template-checkbox")) {
        // Textueel checkboxes zijn exclusief t.o.v. elkaar (niet combineerbaar)
        if (e.target.dataset.mode === 'textueel' && e.target.checked) {
            document.querySelectorAll('.template-checkbox[data-mode="textueel"]').forEach(cb => {
                if (cb !== e.target) cb.checked = false;
            });
        }
        // Sync _flowTextTemplate / _flowUserTextTemplate op basis van actieve textueel checkbox
        const activeTxt = document.querySelector('.template-checkbox[data-mode="textueel"]:checked');
        if (activeTxt) {
            const key = activeTxt.value;
            if (key.startsWith('flow:dept-txt:')) {
                window._flowTextTemplate = window._flowDeptTextTemplateCache || window._flowTextTemplate;
            } else if (key.startsWith('flow:user-txt:')) {
                window._flowTextTemplate = window._flowUserTextTemplate || '';
            }
        }
        createTemplateForms();
        updateActiveTemplateSuffix();
        updateSnomedCtBtn();
        updateAiResultatenBtn();
        _syncCalculatorWindow(e.target);
    }
});

