function setDictationText(text) {
    // Try light DOM first, then shadow DOM
    const el = clipboard.querySelector("textarea, input:not([type=submit]):not([type=button]), [contenteditable='true']")
        || clipboard.shadowRoot?.querySelector("textarea, input:not([type=submit]):not([type=button]), [contenteditable='true']");
    if (el) {
        if ("value" in el) {
            setNativeValue(el, text);
        } else {
            el.innerText = text;
            el.dispatchEvent(new InputEvent("input", { bubbles: true, composed: true }));
        }
    }
    // Also try public property setters the web component may expose
    try { clipboard.value = text; } catch (_) {}
    try { clipboard.text  = text; } catch (_) {}
    // Paste event — tiro-magic-clipboard intercepts clipboard paste
    try {
        const dt = new DataTransfer();
        dt.setData('text/plain', text);
        clipboard.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, composed: true }));
    } catch (_) {}
    latestDictationText = text;
}

