file.content:
let _ttEditorExamId = null;
let _ttEditorLevel = 'dept'; // 'dept' or 'user'

function _setBadgeActive(badgeId, active) {
    const b = document.getElementById(badgeId);
    if (!b) return;
    if (active) {
        b.textContent = 'Actief';
        b.className = 'text-[10px] font-medium text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-1.5 py-0.5 rounded';
    } else {
        b.textContent = 'Inactief';
        b.className = 'text-[10px] font-medium text-red-500 dark:text-red-400 bg-red-50 dark:bg-red-900/20 px-1.5 py-0.5 rounded';
    }
}

window.openTtEditor = function(examId, level) {
    _ttEditorExamId = examId;
    _ttEditorLevel = level || 'dept';
    const et = state.examTypes.find(e => e.id === examId);
    if (!et) return;
    document.getElementById('tt-editor-modal').classList.remove('hidden');
    const levelLabel = _ttEditorLevel === 'user' ? 'Gebruiker — ' : 'Afdeling — ';
    document.getElementById('tt-editor-exam-name').textContent = levelLabel + et.name;
    const ta = document.getElementById('tt-editor-input');
    ta.value = _ttEditorLevel === 'user' ? (et.userTextTemplate || '') : (et.textTemplate || '');
    document.getElementById('tt-editor-labels-toggle').checked = et.labelsDefaultVisible === true;
    syncTtHighlight();
    ta.focus();
};

window.closeTtEditor = function() {
    document.getElementById('tt-editor-modal').classList.add('hidden');
    _ttEditorExamId = null;
};

window.saveTtEditor = function() {
    const ta = document.getElementById('tt-editor-input');
    const val = ta.value.trim();
    if (!_ttEditorExamId) return;
    const et = state.examTypes.find(e => e.id === _ttEditorExamId);
    if (et) {
        if (_ttEditorLevel === 'user') {
            et.userTextTemplate = val;
        } else {
            et.textTemplate = val;
            et.labelsDefaultVisible = document.getElementById('tt-editor-labels-toggle').checked;
        }
    }
    saveData();
    // Sync hidden textarea + badge if slide-over is open for this exam
    if (document.getElementById('slide-over').classList.contains('open') &&
        window._currentEditId === _ttEditorExamId) {
        if (_ttEditorLevel === 'user') {
            const hiddenTa = document.getElementById('edit-user-text-template');
            if (hiddenTa) hiddenTa.value = val;
            _setBadgeActive('user-tt-badge', !!val);
        } else {
            const hiddenTa = document.getElementById('edit-text-template');
            if (hiddenTa) hiddenTa.value = val;
            _setBadgeActive('tt-edit-badge', !!val);
        }
        updateSectionStatuses();
    }
    renderCards();
    closeTtEditor();
};

function syncTtHighlight() {
    const ta = document.getElementById('tt-editor-input');
    const pre = document.getElementById('tt-editor-highlight');
    pre.innerHTML = highlightTt(ta.value) + '\n';
}

window.openTtEditorFromSlideOver = function() {
    if (window._currentEditId) openTtEditor(window._currentEditId, 'dept');
};

window.openLevelTtEditor = function(level) {
    if (window._currentEditId) openTtEditor(window._currentEditId, level);
};

function updateSectionStatuses() {
    const aiRules = editAiRules || [];
    const calcs = editCalculators || [];
    const preset = (document.getElementById('edit-preset-text')?.value || '').trim();
    const aiSt = document.getElementById('ai-section-status');
    if (aiSt) {
        aiSt.textContent = aiRules.length ? `${aiRules.length} regel${aiRules.length !== 1 ? 's' : ''}` : 'geen';
        aiSt.className = 'text-[10px] font-medium px-1.5 py-0.5 rounded ' + (aiRules.length ? 'bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400' : 'text-neutral-400');
    }

