input.old_string:
window.saveTtEditor = function() {
    const ta = document.getElementById('tt-editor-input');
    const val = ta.value.trim();
    if (!_ttEditorExamId) return;
    const et = state.examTypes.find(e => e.id === _ttEditorExamId);
    if (et) {
        if (_ttEditorLevel === 'user') {
            et.userTextTemplate = val;
        } else {
            et.textTemplate = val;
            et.labelsDefaultVisible = document.getElementById('tt-editor-labels-toggle').checked;
        }
    }
    saveData();
    // Sync hidden textarea + badge if slide-over is open for this exam
    if (document.getElementById('slide-over').classList.contains('open') &&
        window._currentEditId === _ttEditorExamId) {
        if (_ttEditorLevel === 'user') {
            const hiddenTa = document.getElementById('edit-user-text-template');
            if (hiddenTa) hiddenTa.value = val;
            _setBadgeActive('user-tt-badge', !!val);
        } else {
            const hiddenTa = document.getElementById('edit-text-template');
            if (hiddenTa) hiddenTa.value = val;
            _setBadgeActive('tt-edit-badge', !!val);
        }
        updateSectionStatuses();
    }
    renderCards();
    closeTtEditor();
};

input.new_string:
window.saveTtEditor = function() {
    const ta = document.getElementById('tt-editor-input');
    const val = ta.value.trim();
    if (!_ttEditorExamId) return;

    // AI-rule textueel template — only updates editAiRules buffer (not saved to state yet)
    if (_ttEditorLevel.startsWith('ai-rule-')) {
        const rIdx = parseInt(_ttEditorLevel.slice('ai-rule-'.length));
        if (editAiRules[rIdx] !== undefined) {
            editAiRules[rIdx].textTemplate = val;
            const aiRuleRow = document.querySelector(`.ai-rule[data-i="${rIdx}"]`);
            if (aiRuleRow) {
                const hiddenTa = aiRuleRow.querySelector('.ai-tpl-txt');
                if (hiddenTa) hiddenTa.value = val;
                const btn = aiRuleRow.querySelector('.ai-tt-trigger');
                if (btn) {
                    const ind = btn.querySelector('.ai-tt-indicator');
                    if (ind) ind.textContent = val ? '📝 Ingesteld ✓' : '📝 Leeg';
                    btn.className = btn.className.replace(/border-\S+\s+text-\S+\s+bg-\S+/, '');
                    if (val) {
                        btn.classList.add('border-teal-300', 'dark:border-teal-700', 'text-teal-600', 'dark:text-teal-400', 'bg-teal-50', 'dark:bg-teal-900/20');
                    } else {
                        btn.classList.add('border-neutral-300', 'dark:border-slate-700', 'text-neutral-500', 'dark:text-neutral-400');
                    }
                }
            }
        }
        closeTtEditor();
        return;
    }

    const et = state.examTypes.find(e => e.id === _ttEditorExamId);
    if (et) {
        if (_ttEditorLevel === 'user') {
            et.userTextTemplate = val;
        } else {
            et.textTemplate = val;
            et.labelsDefaultVisible = document.getElementById('tt-editor-labels-toggle').checked;
        }
    }
    saveData();
    // Sync hidden textarea + badge if slide-over is open for this exam
    if (document.getElementById('slide-over').classList.contains('open') &&
        window._currentEditId === _ttEditorExamId) {
        if (_ttEditorLevel === 'user') {
            const hiddenTa = document.getElementById('edit-user-text-template');
            if (hiddenTa) hiddenTa.value = val;
            _setBadgeActive('user-tt-badge', !!val);
        } else {
            const hiddenTa = document.getElementById('edit-text-template');
            if (hiddenTa) hiddenTa.value = val;
            _setBadgeActive('tt-edit-badge', !!val);
        }
        updateSectionStatuses();
    }
    renderCards();
    closeTtEditor();
};

