const preset = (document.getElementById('edit-preset-text')?.value || '').trim();
const aiSt = document.getElementById('ai-section-status');
if (aiSt) {
    aiSt.textContent = aiRules.length ? `${aiRules.length} regel${aiRules.length !== 1 ? 's' : ''}` : 'geen';
    aiSt.className = 'text-[10px] font-medium px-1.5 py-0.5 rounded ' + (aiRules.length ? 'bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400' : 'text-neutral-400');
}
const calcSt = document.getElementById('calc-section-status');
if (calcSt) {
    calcSt.textContent = calcs.length ? `${calcs.length} gekoppeld` : 'geen';
    calcSt.className = 'text-[10px] font-medium px-1.5 py-0.5 rounded ' + (calcs.length ? 'bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400' : 'text-neutral-400');
}
const presetSt = document.getElementById('preset-section-status');
if (presetSt) {
    presetSt.textContent = preset ? 'ingesteld' : 'geen';
    presetSt.className = 'text-[10px] font-medium px-1.5 py-0.5 rounded ' + (preset ? 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400' : 'text-neutral-400');
}
// Dept mode badge
const deptModeVal = document.querySelector('input[name="dept-mode"]:checked')?.value || 'template';
const deptTpl = (document.getElementById('edit-dept-template')?.value || '').trim();
const deptBadge = document.getElementById('dept-mode-badge');

