// ── Textuele back-up result panel ─────────────────────────────────────────
const ttResultPanel      = document.getElementById('tt-result-panel');
const ttContent          = document.getElementById('tt-content');
const ttStatus           = document.getElementById('tt-status');
const ttActions          = document.getElementById('tt-actions');
const ttToggleOrig       = document.getElementById('tt-toggle-orig');
const ttCopy             = document.getElementById('tt-copy');
const ttToggleLabels     = document.getElementById('tt-toggle-labels');
let _ttOriginalText      = null;
let _ttResultHTML        = null;
let _ttShowingOrig       = false;
let _ttAbort             = null;
let _ttLabelsVisible     = true;

// Wrap [Label:] patterns in the rendered HTML so they can be toggled.
// The outer [ ] brackets are stripped from the visible text; only "Label:" remains.
function wrapSectionLabels(el) {
    el.innerHTML = el.innerHTML.replace(
        /\[([^\]]+?:)\s*\]/g,
        '<span class="tt-section-label">$1</span>'
    );
}

function applyCompactBrs(el) {
    // Read [br]-marked labels from the template definition (not from AI output).
    // Ensures the label span ends with a <br> so the line break is hidden
    // together with the label. If the AI put content on the same line
    // (no BR sibling), we insert one inside the span ourselves.
    const template = window._flowTextTemplate || window._flowUserTextTemplate || '';
    const compactLabels = new Set();
    const re = /\[([^\]]+?:)\s*\]\[br\]/g;
    let m;
    while ((m = re.exec(template)) !== null) compactLabels.add(m[1].trim());
    if (!compactLabels.size) return;
    el.querySelectorAll('.tt-section-label').forEach(span => {
        if (compactLabels.has(span.textContent.trim())) {
            const next = span.nextSibling;
            if (next?.nodeName === 'BR') {
                span.appendChild(next); // move existing BR inside
            } else {
                span.appendChild(el.ownerDocument.createElement('br')); // insert BR inside
            }
        }
    });
}

function applyLabelVisibility() {
    const labels = ttContent.querySelectorAll('.tt-section-label');
    labels.forEach(s => { s.style.display = _ttLabelsVisible ? '' : 'none'; });
    ttToggleLabels.textContent = _ttLabelsVisible ? 'Labels verbergen' : 'Labels tonen';
    ttToggleLabels.classList.toggle('bg-cyan-50', !_ttLabelsVisible);
    ttToggleLabels.classList.toggle('dark:bg-cyan-900/30', !_ttLabelsVisible);
    ttToggleLabels.classList.toggle('border-cyan-300', !_ttLabelsVisible);
    ttToggleLabels.classList.toggle('dark:border-cyan-700', !_ttLabelsVisible);
}

ttToggleLabels.addEventListener('click', () => {
    _ttLabelsVisible = !_ttLabelsVisible;
    applyLabelVisibility();
});

ttToggleOrig.addEventListener('click', () => {
    _ttShowingOrig = !_ttShowingOrig;
    if (_ttShowingOrig) {
        _ttResultHTML = ttContent.innerHTML;
        ttContent.innerHTML = (_ttOriginalText || '').replace(/\n/g, '<br>');
        wrapSectionLabels(ttContent);
        applyCompactBrs(ttContent);
        applyLabelVisibility();
        ttToggleOrig.textContent = 'Toon gecorrigeerd';
    } else {
        ttContent.innerHTML = _ttResultHTML;
        ttToggleOrig.textContent = 'Toon origineel';
        applyLabelVisibility();
    }
});
ttCopy.addEventListener('click', () => {
    navigator.clipboard.writeText(ttContent.innerText).catch(() => {});
});
document.getElementById('tt-send-to-dictation').addEventListener('click', () => {
    sendToDictationFields(ttContent.innerText);
});
document.getElementById('tt-close').addEventListener('click', () => {
    _ttAbort?.abort();
    ttResultPanel.classList.add('hidden');
    _ttLabelsVisible = true;
    ttToggleLabels.classList.remove('bg-cyan-50', 'dark:bg-cyan-900/30', 'border-cyan-300', 'dark:border-cyan-700');
    showTemplatePreview();
});

async function runAutofillBackup(pipRefs, providedText) {
    const tekst = providedText || readDictationText() || _realtimeOriginalText || '';
    if (!tekst) {
        if (pipRefs) pipRefs.pipAlert('Geen dictatietekst gevonden. Dicteer eerst uw bevindingen.');
        else alert("Geen dictatietekst gevonden. Dicteer eerst uw bevindingen.");
        return;
    }
    const typeOnderzoek = extractAnyField("type onderzoek", "type of examination", "onderzoek");
    const ki  = extractAnyField("klinische inlichtingen", "clinical information", "klinisch");
    const dv  = extractAnyField("diagnostische vraagstelling", "diagnostische vraag", "diagnostic question");

