function showTemplatePreview() {
    const preview = document.getElementById('tt-template-preview');
    const code    = document.getElementById('tt-template-preview-code');
    if (!preview || !code || !window._flowTextTemplate) return;
    code.innerHTML = renderTemplatePreviewHtml(window._flowTextTemplate);
    preview.classList.remove('hidden');
}

function hideTemplatePreview() {
    document.getElementById('tt-template-preview')?.classList.add('hidden');
}

function updateTextTemplateBackup() {
    const acc  = document.getElementById('text-template-accordion');
    const suf  = document.getElementById('text-template-suffix');
    if (window._flowTextTemplate || window._flowUserTextTemplate) {
        acc.classList.remove('hidden');
        suf.textContent = '';
        // Show preview only when the result panel is not already visible
        if (document.getElementById('tt-result-panel')?.classList.contains('hidden') !== false) showTemplatePreview();
    } else {
        acc.classList.add('hidden');
        suf.textContent = '';
        hideTemplatePreview();
    }
}

