async function openDictationPopout() {
    if (!window.documentPictureInPicture) {
        alert('Document Picture-in-Picture wordt niet ondersteund. Gebruik Chrome 116+.');
        return;
    }
    try {
        const pipWindow = await window.documentPictureInPicture.requestWindow({ width: 460, height: 560 });
        _pipWindow = pipWindow;
        buildPipUI(pipWindow);
        updateDictationPopoutToggle(true);
        pipWindow.addEventListener('pagehide', closeDictationPopout);
    } catch (err) {
        if (err.name !== 'NotAllowedError') console.warn('PiP fout:', err);
        updateDictationPopoutToggle(false);
    }
}

dictationPopoutToggle.addEventListener('click', async () => {
    if (_pipWindow) {
        _pipWindow.close();
        closeDictationPopout();
    } else {
        await openDictationPopout();
    }
});

