  }

  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { background: var(--bg); color: var(--text); font-family: system-ui, -apple-system, sans-serif; padding: 1.5rem 1rem 3rem; line-height: 1.5; }

  h1 { font-size: 1.1rem; font-weight: 700; letter-spacing: -.01em; margin-bottom: .25rem; }
  .subtitle { font-size: .8rem; color: var(--muted); margin-bottom: 1.75rem; }

