  @media (max-width: 860px) { .grid { grid-template-columns: 1fr; } }

  .col { background: var(--surface); border: 1px solid var(--border); border-radius: .6rem; overflow: hidden; display: flex; flex-direction: column; }
  .col-header { padding: .75rem 1rem .6rem; border-bottom: 1px solid var(--border); }
