  .legend { display: flex; flex-wrap: wrap; gap: .5rem 1rem; margin-top: 1.25rem; padding: .75rem 1rem; background: var(--surface); border: 1px solid var(--border); border-radius: .5rem; }
  .legend-item { display: flex; align-items: center; gap: .4rem; font-size: .72rem; color: var(--muted); }
