                _realtimeCorrectedText = null;
                realtimeActions.style.display = 'none';
                realtimeToggleOrig.style.display = 'none';
                realtimeToggleOrig.textContent = '↩ Origineel';
                // Keep previous result visible until first new chunk arrives

                const template = verslagCheckUrlInput.value.trim() || DEFAULT_VERSLAG_CHECK_PROMPT;
                const typeOnderzoek = extractAnyField("type onderzoek", "type of examination", "onderzoek");
                const ki = extractAnyField("klinische inlichtingen", "clinical information", "klinisch");
                const dv = extractAnyField("diagnostische vraagstelling", "diagnostische vraag", "diagnostic question");
                const patientInfo = extractPatientInfo();
                const prompt = fillPrompt(template, { tekst, type_onderzoek: typeOnderzoek, klinische_inlichtingen: ki, diagnostische_vraagstelling: dv, patient_info: patientInfo, text_template: window._flowTextTemplate || '' });

                let firstChunk = true;
                let streamedText = '';
                try {
                    await callGeminiStream(getModel('geminiModelRealtime'), prompt, (partial) => {
                        if (firstChunk) { realtimeContent.innerHTML = ''; firstChunk = false; }
                        streamedText = partial;
                        realtimeContent.innerHTML = partial.replace(/\n/g, '<br>');
                        realtimeStatus.textContent = '';
                    }, _realtimeAbort.signal);
                    _realtimeCorrectedText = extractCleanCorrection(streamedText);
                    realtimeContent.innerHTML = computeDiffHTMLStructured(tekst, _realtimeCorrectedText);
                    realtimeActions.style.display = 'flex';
                    realtimeToggleOrig.style.display = _realtimeOriginalText ? 'inline-block' : 'none';
                } catch (e) {
                    if (e.name !== 'AbortError') {
                        realtimeStatus.textContent = 'Fout: ' + e.message;
                    }
                }
            }

            realtimeToggleOrig.addEventListener('click', () => {
                _realtimeShowingOriginal = !_realtimeShowingOriginal;
                if (_realtimeShowingOriginal) {
                    _realtimeResultHTML = realtimeContent.innerHTML;
                    realtimeContent.innerHTML = _realtimeOriginalText.replace(/\n/g, '<br>');
                    realtimeToggleOrig.textContent = '↩ Gecorrigeerd';
                } else {
                    realtimeContent.innerHTML = _realtimeResultHTML;
                    realtimeToggleOrig.textContent = '↩ Origineel';
                }
            });

            realtimeCopy.addEventListener('click', () => {
                navigator.clipboard.writeText(
                    _realtimeShowingOriginal ? _realtimeOriginalText : getRealtimeText(realtimeContent)
                ).catch(() => {});
                realtimePanel.classList.add('hidden');   // kopiëren sluit het realtime verslag check-venster
            });
            document.getElementById('realtime-send-to-dictation').addEventListener('click', () => {
                const text = _realtimeShowingOriginal ? _realtimeOriginalText : getRealtimeText(realtimeContent);
                if (text) sendToDictationFields(text);
            });

            function scheduleRealtimeCheck() {
                // When the PiP window is open, realtime check runs there instead
                if (_pipWindow && !_pipWindow.closed) return;
                clearTimeout(_realtimeDebounce);
                _realtimeDebounce = setTimeout(() => {
                    const tekst = readDictationText().trim();
                    if (!tekst || tekst === _realtimeLastText) return;
                    // Only check when the last non-empty line ends with sentence-ending punctuation
                    const lastLine = tekst.split('\n').map(l => l.trim()).filter(Boolean).pop();
                    if (!lastLine || !/[.!?]$/.test(lastLine)) return;
                    _realtimeLastText = tekst;
                    runRealtimeCheck(tekst);
                }, 2000);
            }




