// ── Automatische onderzoek herkenning en selectie ──────────────────
const autoStudyDetectToggle = document.getElementById('auto-study-detect-toggle');
let autoStudyDetect = localStorage.getItem('autoStudyDetect') === 'true';
let _autoStudyDebounce = null;
let _autoStudyLastDetected = ''; // voorkom herhaalde triggers voor zelfde onderzoek

function updateAutoStudyDetectToggle() {
    autoStudyDetectToggle.setAttribute('aria-checked', String(autoStudyDetect));
    autoStudyDetectToggle.className = `relative inline-flex h-5 w-9 flex-shrink-0 items-center rounded-full transition-colors focus:outline-none ${autoStudyDetect ? 'bg-cyan-600' : 'bg-neutral-300 dark:bg-neutral-600'}`;
    autoStudyDetectToggle.querySelector('span').className = `inline-block h-3.5 w-3.5 rounded-full bg-white shadow transition-transform ${autoStudyDetect ? 'translate-x-[19px]' : 'translate-x-[3px]'}`;
}
autoStudyDetectToggle.addEventListener('click', () => {
    autoStudyDetect = !autoStudyDetect;
    localStorage.setItem('autoStudyDetect', String(autoStudyDetect));
    updateAutoStudyDetectToggle();
});
updateAutoStudyDetectToggle();

function _tryAutoDetectStudyType(text) {
    if (!autoStudyDetect) return;
    for (const line of text.split('\n')) {
        const trimmed = line.replace(/\s+$/, '');
        // Moet eindigen op : + bekende modaliteit + NIET al in hoofdletters
        if (!/:$/.test(trimmed)) continue;
        if (!_EXAM_MODALITEIT.test(trimmed)) continue;
        if (trimmed === trimmed.toUpperCase()) return; // al herkend, niet opnieuw triggeren
        const candidate = trimmed.replace(/:$/, '').trim();
        if (candidate === _autoStudyLastDetected) return; // zelfde als vorige keer
        _autoStudyLastDetected = candidate;
        // Vul "type onderzoek" in en selecteer het bijhorende template
        if (contextForm) deepFillByLabel(contextForm, "type onderzoek", candidate);
        updateTemplatesFromFlow(candidate);
        return;
    }
}

clipboard.addEventListener('input', () => {
    if (!autoStudyDetect) return;
    clearTimeout(_autoStudyDebounce);
    _autoStudyDebounce = setTimeout(() => {
        const tekst = readDictationText().trim();
        if (tekst) _tryAutoDetectStudyType(tekst);
    }, 600);
}, true);

