input.old_string:
function _tryAutoDetectStudyType(text) {
    if (!autoStudyDetect) return;
    for (const line of text.split('\n')) {
        const trimmed = line.replace(/\s+$/, '');
        // Moet eindigen op : + bekende modaliteit + NIET al in hoofdletters
        if (!/:$/.test(trimmed)) continue;
        if (!_EXAM_MODALITEIT.test(trimmed)) continue;
        if (trimmed === trimmed.toUpperCase()) return; // al herkend, niet opnieuw triggeren
        const candidate = trimmed.replace(/:$/, '').trim();
        if (candidate === _autoStudyLastDetected) return; // zelfde als vorige keer
        _autoStudyLastDetected = candidate;
        // Vul "type onderzoek" in en selecteer het bijhorende template
        if (contextForm) deepFillByLabel(contextForm, "type onderzoek", candidate);
        updateTemplatesFromFlow(candidate);
        return;
    }
}

input.new_string:
// Herkent lateraliteitssuffix aan het einde van een onderzoeksnaam
// bv. "echo enkel links" → { type: "echo enkel", lat: "Links" }
const _LATERALITY_RE = /\s+(links|rechts|bilateraal|beiderzijds)$/i;
const _LATERALITY_MAP = { links: 'Links', rechts: 'Rechts', bilateraal: 'Bilateraal', beiderzijds: 'Bilateraal' };

function _tryAutoDetectStudyType(text) {
    if (!autoStudyDetect) return;
    for (const line of text.split('\n')) {
        const trimmed = line.replace(/\s+$/, '');
        // Moet eindigen op : + bekende modaliteit + NIET al in hoofdletters
        if (!/:$/.test(trimmed)) continue;
        if (!_EXAM_MODALITEIT.test(trimmed)) continue;
        if (trimmed === trimmed.toUpperCase()) return; // al herkend, niet opnieuw triggeren
        const candidate = trimmed.replace(/:$/, '').trim();
        if (candidate === _autoStudyLastDetected) return; // zelfde als vorige keer
        _autoStudyLastDetected = candidate;

        // Splits lateraliteit van het onderzoekstype
        const latMatch = candidate.match(_LATERALITY_RE);
        const typeOnderzoek = latMatch ? candidate.slice(0, latMatch.index).trim() : candidate;
        const lateraliteit  = latMatch ? _LATERALITY_MAP[latMatch[1].toLowerCase()] : null;

        if (contextForm) {
            deepFillByLabel(contextForm, "type onderzoek", typeOnderzoek);
            if (lateraliteit) deepFillDropdownByLabel(contextForm, "lateralisatie", lateraliteit).catch(() => {});
        }
        updateTemplatesFromFlow(typeOnderzoek);
        return;
    }
}

