// Dictation popout (Document PiP — textarea + realtime check)
// ============================================
const dictationPopoutToggle = document.getElementById('dictation-popout-toggle');
let _pipRealtimeAbort = null;
let _pipRealtimeDebounce = null;
let _pipRealtimeLastText = '';
let _pipTtRef = null;

function updateDictationPopoutToggle(active) {
    dictationPopoutToggle.setAttribute('aria-checked', String(active));
    dictationPopoutToggle.className = `relative inline-flex h-5 w-9 flex-shrink-0 items-center rounded-full transition-colors focus:outline-none ${active ? 'bg-cyan-600' : 'bg-neutral-300 dark:bg-neutral-600'}`;
    dictationPopoutToggle.querySelector('span').className = `inline-block h-3.5 w-3.5 rounded-full bg-white shadow transition-transform ${active ? 'translate-x-[19px]' : 'translate-x-[3px]'}`;
    localStorage.setItem('pipActive', active ? '1' : '0');
}

function closeDictationPopout() {
    _pipRealtimeAbort?.abort();
    clearTimeout(_pipRealtimeDebounce);
    _ttAbort?.abort();
    _pipWindow = null;
    _pipTtRef = null;
    _pipDmoTa = null;
    _pipUpdateStudyHeader = null;
    _pipRealtimeLastText = '';
    updateDictationPopoutToggle(false);
}

function buildPipUI(pipWindow) {
    // Copy styles from main page
    [...document.styleSheets].forEach(sheet => {
        try {
            const css = [...sheet.cssRules].map(r => r.cssText).join('');
            const style = pipWindow.document.createElement('style');
            style.textContent = css;
            pipWindow.document.head.appendChild(style);
        } catch {
            if (sheet.href) {
                const link = pipWindow.document.createElement('link');
                link.rel = 'stylesheet'; link.href = sheet.href;
                pipWindow.document.head.appendChild(link);
            }
        }
    });
    if (document.documentElement.classList.contains('dark')) {
        pipWindow.document.documentElement.classList.add('dark');
    }
    // Custom scrollbar style for DMO textarea
    const _pipScrollStyle = pipWindow.document.createElement('style');
    _pipScrollStyle.textContent = [
        '.pip-dmo-ta::-webkit-scrollbar{width:4px}',
        '.pip-dmo-ta::-webkit-scrollbar-track{background:transparent}',
        '.pip-dmo-ta::-webkit-scrollbar-thumb{background:rgba(148,163,184,0.35);border-radius:9999px}',
        '.pip-dmo-ta::-webkit-scrollbar-thumb:hover{background:rgba(148,163,184,0.65)}',
        '.pip-dmo-ta{scrollbar-width:thin;scrollbar-color:rgba(148,163,184,0.35) transparent}',
        '.dark .pip-dmo-ta::-webkit-scrollbar-thumb{background:rgba(100,116,139,0.35)}',
        '.dark .pip-dmo-ta::-webkit-scrollbar-thumb:hover{background:rgba(100,116,139,0.65)}',
    ].join('');
    pipWindow.document.head.appendChild(_pipScrollStyle);
    pipWindow.document.body.style.cssText = 'margin:0;padding:0;overflow-y:auto;';
    pipWindow.document.body.className = 'bg-neutral-50 dark:bg-[#161f27] text-neutral-800 dark:text-neutral-200';

