const mk = (tag, cls, text) => {
    const el = pipWindow.document.createElement(tag);
    if (cls) el.className = cls;
    if (text !== undefined) el.textContent = text;
    return el;
};

const wrap = mk('div', 'flex flex-col gap-3');
wrap.style.cssText = 'padding:8px;box-sizing:border-box;';

// ── Study info header (type onderzoek + lateralisatie) ──────────
const studyInfoHeader = mk('div', 'text-xs font-semibold text-neutral-600 dark:text-neutral-300 text-center tracking-wide leading-snug');
_pipUpdateStudyHeader = function() {
    // Specific terms only — "type onderzoek" won't match "datum onderzoek"
    const typeRaw = extractAnyField("type onderzoek", "type of examination") || pacsTypeOnderzoek || '';
    const lat     = extractAnyField("lateralisatie", "laterality") || pacsLateralisatie || '';
    // Multiple studies may be pipe- or semicolon-separated
    const types = typeRaw ? typeRaw.split(/[|;]+/).map(t => t.trim()).filter(Boolean) : [];
    const parts = [...types];
    if (lat) parts.push(lat);
    studyInfoHeader.textContent = parts.join(', ');
    studyInfoHeader.style.display = parts.length ? '' : 'none';
};
_pipUpdateStudyHeader();
wrap.appendChild(studyInfoHeader);

// ── Dictation textarea (DMO input) ──────────────────
const ta = pipWindow.document.createElement('textarea');
ta.rows = 5;
ta.placeholder = 'Dicteer hier via DMO…';
ta.className = 'pip-dmo-ta w-full px-3 py-2 text-sm rounded-lg border border-neutral-300 dark:border-slate-700 bg-white dark:bg-muted text-neutral-800 dark:text-neutral-200 focus:outline-none focus:ring-2 focus:ring-cyan-500 resize-none leading-relaxed';
ta.style.minHeight = '130px';
ta.style.overflowY = 'auto';
ta.style.height = '130px'; // initial; recalcTaHeight() will override
// _autoGrow is a no-op: recalcTaHeight handles the height; ta scrolls internally
const _autoGrow = () => {};
wrap.appendChild(ta);
_pipDmoTa = ta;

// ── Inline correction mode (contenteditable) ────────
const _pipInlineMode = false; // inline toggle removed; always use textarea
const _inlineCache = new Map(); // rawText → corrHTML (null = pending)
let _inlineDebounce = null;

const ce = pipWindow.document.createElement('div');
ce.contentEditable = 'true';
ce.className = ta.className.replace('resize-none', '');
ce.style.cssText = 'min-height:80px;max-height:300px;overflow-y:auto;white-space:pre-wrap;word-break:break-word;cursor:text;box-sizing:border-box';
const _ceFirstDiv = pipWindow.document.createElement('div');
_ceFirstDiv.innerHTML = '<br>';
ce.appendChild(_ceFirstDiv);
ce.style.display = 'none';
ta.style.display = '';
wrap.appendChild(ce);

function getCeText() {
    const divs = Array.from(ce.children);
    if (!divs.length) return ce.textContent;
    return divs.map(div => {
        if (div.childNodes.length === 1 && div.firstChild.nodeName === 'BR') return '';
        return getRealtimeText(div).replace(/\n+$/, '');
    }).join('\n').replace(/\n+$/, '');
}

function getCursorLineDiv() {
    const sel = pipWindow.getSelection();
    if (!sel || !sel.rangeCount) return null;
    let node = sel.getRangeAt(0).startContainer;
    while (node && node !== ce) {
        if (node.parentElement === ce) return node.nodeType === 1 ? node : node.parentElement;
        node = node.parentElement;
    }
    return null;
}

async function checkInlineLines(requirePeriod = true) {
    if (!_pipInlineMode || !realtimeEnabled || !GEMINI_API_KEY) return;
    const cursorDiv = getCursorLineDiv();
    for (const div of Array.from(ce.children)) {
        if (div === cursorDiv) continue;
        if (div.dataset.dirty) {
            div.textContent = div.textContent;
            delete div.dataset.dirty;
        }
        if (div.dataset.rawText) continue;
        const rawText = div.textContent.trim();
        if (!rawText) continue;
        // Only check sentences that end with punctuation (unless triggered by Enter)
        if (requirePeriod && !/[.!?]$/.test(rawText)) continue;
        if (_inlineCache.has(rawText)) {
            const h = _inlineCache.get(rawText);
            if (h) { div.dataset.rawText = rawText; div.innerHTML = h; }
            continue;
        }
        _inlineCache.set(rawText, null);
        div.dataset.rawText = rawText;
        div.dataset.checking = '1';
        const capturedText = rawText;
        const capturedDiv = div;
        (async () => {
            try {
                const template = inlineCheckUrlInput.value.trim() || DEFAULT_INLINE_CHECK_PROMPT;
                const typeOnderzoek = extractAnyField('type onderzoek', 'type of examination', 'onderzoek');
                const ki = extractAnyField('klinische inlichtingen', 'clinical information', 'klinisch');
                const dv = extractAnyField('diagnostische vraagstelling', 'diagnostische vraag', 'diagnostic question');
                const pat = extractPatientInfo();
                const volledigeTekst = getCeText();
                const prompt = fillPrompt(template, { tekst: capturedText, type_onderzoek: typeOnderzoek, klinische_inlichtingen: ki, diagnostische_vraagstelling: dv, patient_info: pat, volledige_tekst: volledigeTekst });
                let full = '';
                await callGeminiStream(getModel('geminiModelRealtime'), prompt, p => { full = p; }, undefined);
                // Take only the first non-empty line — prevents AI from returning multiple sentences
                const corrText = extractCleanCorrection(full).split('\n').map(l => l.trim()).filter(Boolean)[0] || capturedText;
                const corrHTML = computeDiffHTML(capturedText, corrText);
                _inlineCache.set(capturedText, corrHTML);
                if (capturedDiv.dataset.rawText === capturedText) {
                    delete capturedDiv.dataset.checking;
                    capturedDiv.innerHTML = corrHTML;
                }
            } catch(e) {

