            try {
                const result = await callGemini(getModel('geminiModelTranslate'), prompt, _newGeminiSignal());
                trContent.innerHTML = renderMarkdown(result);
                trStatus.textContent = '';
                trActions.style.display = 'flex';
                trOrigBtn.style.display = _trOrigText ? '' : 'none';
