const pipTtStatus = mk('span', 'flex items-center gap-1.5 text-xs text-neutral-400 dark:text-neutral-500', '');
const pipTtCloseBtn = mk('button', 'text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 leading-none cursor-pointer', '×');
pipTtCloseBtn.type = 'button';
pipTtCloseBtn.title = 'Sluiten';
pipTtCloseBtn.addEventListener('click', () => {
    _ttAbort?.abort();
    pipTtPanel.style.display = 'none';
});
const pipTtRightHead = mk('div', 'flex items-center gap-2');
pipTtRightHead.append(pipTtStatus, pipTtCloseBtn);
pipTtHead.append(pipTtTitle, pipTtRightHead);
const pipTtContent = mk('div', 'px-3 py-2 text-sm text-neutral-700 dark:text-neutral-200 min-h-[60px] leading-relaxed');
const pipTtActions = mk('div', 'items-center gap-2 px-3 py-2 border-t border-neutral-200 dark:border-slate-700 bg-neutral-50 dark:bg-muted');
pipTtActions.style.display = 'none';

let _pipTtOrigText = null, _pipTtShowingOrig = false, _pipTtResultHTML = null;
let _pipTtLabelsVisible = true;

function pipTtApplyLabels() {
    pipTtContent.querySelectorAll('.tt-section-label').forEach(s => {
        s.style.display = _pipTtLabelsVisible ? '' : 'none';
    });
    pipTtLabelsBtn.textContent = _pipTtLabelsVisible ? 'Labels verbergen' : 'Labels tonen';
    pipTtLabelsBtn.classList.toggle('bg-cyan-50', !_pipTtLabelsVisible);
    pipTtLabelsBtn.classList.toggle('dark:bg-cyan-900/30', !_pipTtLabelsVisible);
    pipTtLabelsBtn.classList.toggle('border-cyan-300', !_pipTtLabelsVisible);
    pipTtLabelsBtn.classList.toggle('dark:border-cyan-700', !_pipTtLabelsVisible);
}

const pipTtToggle = mkBtn(SM.replace('cursor-pointer','') + ' cursor-pointer', 'Toon origineel', () => {
    _pipTtShowingOrig = !_pipTtShowingOrig;
    if (_pipTtShowingOrig) {
        _pipTtResultHTML = pipTtContent.innerHTML;
        pipTtContent.innerHTML = (_pipTtOrigText || '').replace(/\n/g, '<br>');
        wrapSectionLabels(pipTtContent);
        applyCompactBrs(pipTtContent);
        pipTtApplyLabels();
        pipTtToggle.textContent = 'Toon gecorrigeerd';
    } else {
        pipTtContent.innerHTML = _pipTtResultHTML;
        pipTtToggle.textContent = 'Toon origineel';
        pipTtApplyLabels();
    }
});
pipTtToggle.style.display = 'none';

const pipTtLabelsBtn = mkBtn(SM.replace('cursor-pointer','') + ' cursor-pointer', 'Labels verbergen', () => {
    _pipTtLabelsVisible = !_pipTtLabelsVisible;
    pipTtApplyLabels();
});
pipTtLabelsBtn.style.display = 'none';

const pipTtCopyBtn = mkBtn(SM.replace('cursor-pointer','') + ' cursor-pointer', 'Kopiëren', (e) => {
    const btn = e.currentTarget;
    pipCopy(pipTtContent.innerText || '');
    const orig = btn.textContent;
    btn.textContent = 'Gekopieerd ✓';
    btn.style.color = '#16a34a';
    setTimeout(() => { btn.textContent = orig; btn.style.color = ''; }, 2000);
});

const pipTtSendBtn = mkSendBtn(() => pipTtContent.innerText || '', pipTtPanel);
pipTtActions.append(pipTtToggle, pipTtLabelsBtn, pipTtCopyBtn, pipTtSendBtn);
pipTtPanel.append(pipTtHead, pipTtContent, pipTtActions);
wrap.appendChild(pipTtPanel);

// Build ref object for runAutofillBackup
_pipTtRef = {
    panel:       pipTtPanel,
    content:     pipTtContent,
    status:      pipTtStatus,
    actions:     pipTtActions,
    toggle:      pipTtToggle,
    labelsBtn:   pipTtLabelsBtn,
    applyLabels: pipTtApplyLabels,
    rtPanel:     rtPanel,
    get origText()      { return _pipTtOrigText; },
    set origText(v)     { _pipTtOrigText = v; },
    get showingOrig()   { return _pipTtShowingOrig; },
    set showingOrig(v)  { _pipTtShowingOrig = v; },
    get resultHTML()    { return _pipTtResultHTML; },
    set resultHTML(v)   { _pipTtResultHTML = v; },
