const dictationPopoutToggle = document.getElementById('dictation-popout-toggle');
let _pipRealtimeAbort = null;
let _pipRealtimeDebounce = null;
let _pipRealtimeLastText = '';
let _pipTtRef = null;

function updateDictationPopoutToggle(active) {
    dictationPopoutToggle.setAttribute('aria-checked', String(active));
    dictationPopoutToggle.className = `relative inline-flex h-5 w-9 flex-shrink-0 items-center rounded-full transition-colors focus:outline-none ${active ? 'bg-cyan-600' : 'bg-neutral-300 dark:bg-neutral-600'}`;
    dictationPopoutToggle.querySelector('span').className = `inline-block h-3.5 w-3.5 rounded-full bg-white shadow transition-transform ${active ? 'translate-x-[19px]' : 'translate-x-[3px]'}`;
    localStorage.setItem('pipActive', active ? '1' : '0');
}

