let _cachedModels = null;

async function fetchModels() {
    const apiKey = localStorage.getItem("geminiApiKey");
    if (!apiKey) return null;
    try {
        const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${apiKey}&pageSize=100`);
        if (!res.ok) return null;
        const data = await res.json();
        return (data.models || [])
            .filter(m => m.supportedGenerationMethods?.includes("generateContent") && m.name.includes("gemini"))
            .map(m => m.name.replace("models/", ""))
            .sort((a, b) => b.localeCompare(a));
    } catch { return null; }
}

async function loadModels() {
    const models = await fetchModels();
    _cachedModels = models;
    if (!models) {
        MODEL_CONFIGS.forEach(cfg => {
            const sel = document.getElementById(cfg.id);
            sel.innerHTML = `<option value="${cfg.defaultModel}">${cfg.defaultModel} (standaard)</option>`;
            sel.value = localStorage.getItem(cfg.storageKey) || cfg.defaultModel;
        });
        return;
    }
    MODEL_CONFIGS.forEach(cfg => {
        const sel = document.getElementById(cfg.id);
        const saved = localStorage.getItem(cfg.storageKey) || cfg.defaultModel;
        sel.innerHTML = models.map(id => `<option value="${id}"${id === saved ? " selected" : ""}>${id}</option>`).join("");
        if (!models.includes(saved)) {
            sel.innerHTML = `<option value="${saved}" selected>${saved} ⚠ niet beschikbaar</option>` + sel.innerHTML;
        }
    });
}

async function useRecommended() {
    const btn = document.getElementById("use-recommended-btn");
    const origHTML = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<svg class="animate-spin" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/></svg> Bezig…';

    const models = await fetchModels() || _cachedModels;
    _cachedModels = models;

    MODEL_CONFIGS.forEach(cfg => {
        const sel = document.getElementById(cfg.id);
        const prefs = RECOMMENDED_MODELS[cfg.storageKey] || [];
        let chosen = cfg.defaultModel;
        if (models) {
            for (const pref of prefs) {
                if (models.includes(pref)) { chosen = pref; break; }
            }
            // Rebuild options with fresh list
            sel.innerHTML = models.map(id => `<option value="${id}">${id}</option>`).join("");
            if (!models.includes(chosen)) {
                sel.innerHTML = `<option value="${chosen}">${chosen}</option>` + sel.innerHTML;
            }
        }
        sel.value = chosen;
        localStorage.setItem(cfg.storageKey, chosen);
    });

    btn.disabled = false;
    btn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg> Bijgewerkt';
    setTimeout(() => { btn.innerHTML = origHTML; }, 2500);
}

// Save model selection on change
MODEL_CONFIGS.forEach(cfg => {
    const sel = document.getElementById(cfg.id);
    sel.value = localStorage.getItem(cfg.storageKey) || cfg.defaultModel;
    sel.addEventListener("change", () => localStorage.setItem(cfg.storageKey, sel.value));
});

// Reload button (↺) — just refreshes the list
document.getElementById("reload-models-btn").addEventListener("click", loadModels);

// "Modellen updaten" button — picks best available per task

