async function useRecommended() {
    const btn = document.getElementById("use-recommended-btn");
    const origHTML = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<svg class="animate-spin" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/></svg> Bezig…';

    const models = await fetchModels() || _cachedModels;
    _cachedModels = models;

    MODEL_CONFIGS.forEach(cfg => {
        const sel = document.getElementById(cfg.id);
        const prefs = RECOMMENDED_MODELS[cfg.storageKey] || [];
        let chosen = cfg.defaultModel;
        if (models) {
            for (const pref of prefs) {
                if (models.includes(pref)) { chosen = pref; break; }
            }
            // Rebuild options with fresh list
            sel.innerHTML = models.map(id => `<option value="${id}">${id}</option>`).join("");
            if (!models.includes(chosen)) {
                sel.innerHTML = `<option value="${chosen}">${chosen}</option>` + sel.innerHTML;
            }
        }
        sel.value = chosen;
        localStorage.setItem(cfg.storageKey, chosen);
    });

    btn.disabled = false;
    btn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg> Bijgewerkt';
    setTimeout(() => { btn.innerHTML = origHTML; }, 2500);
}

