    targetToggle.style.display = (vcAfterAutofillEnabled && backupPlainText) ? 'inline-flex' : 'none';
    // Wrap [Label:] patterns and show toggle button if any labels are present.
    // Use backupPlainText (phase 1 output) to detect labels so the button shows
    // even when the verslag check (phase 2) strips them from the final output.
    const hasLabels = /\[[^\]]+?:\s*\]/.test(backupPlainText);
    if (isMain) {
        _ttLabelsVisible = window._flowLabelsDefaultVisible !== false;
        wrapSectionLabels(ttContent);
        applyCompactBrs(ttContent);
        ttToggleLabels.style.display = hasLabels ? '' : 'none';
        ttToggleLabels.classList.remove('hidden');
        applyLabelVisibility();
    } else if (pipRefs?.labelsBtn) {
        pipRefs.labelsVisible = window._flowLabelsDefaultVisible !== false;
        wrapSectionLabels(targetContent);
        applyCompactBrs(targetContent);
        pipRefs.labelsBtn.style.display = hasLabels ? '' : 'none';
        pipRefs.applyLabels();
    }
} catch (e) {
    targetStatus.innerHTML = '';
    if (e.name !== 'AbortError') targetContent.innerHTML = '<span class="text-red-500">Fout: ' + e.message + '</span>';
}

