                const BLOBS = {
                    "secret-copy-btn":   "XkYgSRDJ4FR0d+q2t95wkezNOaQrrmnGeml5028FJwmSGPTDd94PvEu7r5P9MYPwP6homGyBC8hjd/rBddQ2EMRvUGeVwx0XGx3fxfexqJcXuZ8+UtSYOizWmUefs5jWDg==",
                    "secret-copy-btn-2": "CU+PYNGYBe1AHdjk7k+uBiUj0w4NKvbCCWjsgWD9/fMIxo6iUBHTNWwBzxLHIxNwSiCrA+44bZVvfA3SrHBNOnyx64IuwqqrAIEsLiIV9iHK8zQ=",
                };
                const pinModal = document.getElementById("pin-modal");
                const pinInput = document.getElementById("pin-input");
                const pinError = document.getElementById("pin-error");
                let activeBlob = null;

                async function decrypt(blob, pin) {
                    const data = Uint8Array.from(atob(blob), c => c.charCodeAt(0));
                    const salt = data.slice(0, 16), iv = data.slice(16, 28), enc = data.slice(28);
                    const km = await crypto.subtle.importKey("raw", new TextEncoder().encode(pin), "PBKDF2", false, ["deriveKey"]);
                    const key = await crypto.subtle.deriveKey(
                        { name: "PBKDF2", salt, iterations: 100000, hash: "SHA-256" },
                        km, { name: "AES-GCM", length: 256 }, false, ["decrypt"]
                    );
                    const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, enc);
                    return new TextDecoder().decode(plain);
                }

                function openPinModal(blob) {
                    activeBlob = blob;
                    pinInput.value = "";
                    pinError.classList.add("hidden");
                    pinModal.classList.remove("hidden");
                    setTimeout(() => pinInput.focus(), 50);
                }

                function closePinModal() {
                    pinModal.classList.add("hidden");
                    pinInput.value = "";
                    activeBlob = null;
                }

                async function tryDecrypt() {
                    const pin = pinInput.value;
                    if (!pin || !activeBlob) return;
                    // Start decrypt and clipboard simultaneously to preserve user-gesture context
                    const decryptPromise = decrypt(activeBlob, pin);
                    try {
                        await navigator.clipboard.write([
                            new ClipboardItem({ "text/plain": decryptPromise.then(v => new Blob([v], { type: "text/plain" })) })
                        ]);
                        await decryptPromise;
                        closePinModal();
                    } catch {
                        // If ClipboardItem not supported, fall back to writeText
                        try {
                            const value = await decryptPromise;
                            await navigator.clipboard.writeText(value);
                            closePinModal();
                        } catch {
                            pinError.classList.remove("hidden");
                            pinInput.value = "";
                            pinInput.focus();
                        }
                    }
                }

                Object.entries(BLOBS).forEach(([id, blob]) => {
                    document.getElementById(id).addEventListener("click", () => openPinModal(blob));
                });
                document.getElementById("pin-ok").addEventListener("click", tryDecrypt);
                document.getElementById("pin-cancel").addEventListener("click", closePinModal);
                pinInput.addEventListener("keydown", (e) => {
                    if (e.key === "Enter") tryDecrypt();
                    if (e.key === "Escape") closePinModal();
                });
                pinModal.addEventListener("click", (e) => { if (e.target === pinModal) closePinModal(); });
            })();
        </script>
    </body>
</html>

