document.getElementById('export-import-modal').addEventListener('click', (e) => {
    if (e.target === document.getElementById('export-import-modal'))
        document.getElementById('export-import-modal').classList.add('hidden');
});

document.getElementById('do-export-btn').addEventListener('click', () => {
    const payload = {
        version: '1.0',
        timestamp: new Date().toISOString(),
        flowConfig_v1: JSON.parse(localStorage.getItem('flowConfig_v1') || 'null'),
        textTemplateLogic: localStorage.getItem('textTemplateLogic') || null,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'flow-config-' + new Date().toISOString().slice(0,10) + '.json';
    a.click();
    URL.revokeObjectURL(url);
});

document.getElementById('import-file-input').addEventListener('change', async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    try {
        const text = await file.text();
        const data = JSON.parse(text);
        if (!confirm('Huidige configuratie overschrijven met de geïmporteerde data?')) {
            e.target.value = '';
            return;
        }
        if (data.flowConfig_v1) localStorage.setItem('flowConfig_v1', JSON.stringify(data.flowConfig_v1));
        if (data.textTemplateLogic) localStorage.setItem('textTemplateLogic', data.textTemplateLogic);
        alert('Configuratie succesvol geïmporteerd. De pagina wordt herladen.');
        location.reload();
    } catch {
        alert('Ongeldig bestand. Zorg dat het een geldig JSON-exportbestand is.');
        e.target.value = '';
    }
});

