medgemmaActionUrlInput.value = savedMedgemma || DEFAULT_MEDGEMMA_PROMPT;
if (!savedMedgemma) localStorage.setItem("medgemmaPromptVersion", MEDGEMMA_PROMPT_VERSION);
medgemmaActionUrlInput.addEventListener("input", () => {
    localStorage.setItem("medgemmaActionUrl", medgemmaActionUrlInput.value);
    localStorage.setItem("medgemmaPromptVersion", MEDGEMMA_PROMPT_VERSION);
});

let medgemmaImageBase64 = null;
let medgemmaImageMime   = null;

function handleMedgemmaFile(file) {
    if (!file || !file.type.startsWith("image/")) return;
    if (file.size > 10 * 1024 * 1024) { alert("Afbeelding is groter dan 10 MB. Kies een kleinere afbeelding."); return; }
    const reader = new FileReader();
    reader.onload = (e) => {
        const dataUrl = e.target.result;
        medgemmaImageBase64 = dataUrl.split(",")[1];
        medgemmaImageMime   = file.type;
        medgemmaPreviewImg.src = dataUrl;
        medgemmaPreview.classList.remove("hidden");
        medgemmaDropzone.classList.add("hidden");
    };
    reader.readAsDataURL(file);
}

medgemmaDropzone.addEventListener("click", () => medgemmaFileInput.click());
medgemmaFileInput.addEventListener("change", (e) => handleMedgemmaFile(e.target.files[0]));
medgemmaDropzone.addEventListener("dragover", (e) => {
    e.preventDefault();
    medgemmaDropzone.classList.add("ring-2", "ring-cyan-500");
});
medgemmaDropzone.addEventListener("dragleave", () => {
    medgemmaDropzone.classList.remove("ring-2", "ring-cyan-500");
});
medgemmaDropzone.addEventListener("drop", (e) => {
    e.preventDefault();
    medgemmaDropzone.classList.remove("ring-2", "ring-cyan-500");
    handleMedgemmaFile(e.dataTransfer.files[0]);
});
document.addEventListener("paste", (e) => {
    if (medgemmaAccordion.classList.contains("hidden")) return;
    if (!medgemmaAccordion.open) return;
    // Don't intercept when a text field or web component (e.g. tiro-form-filler) is active
    const tag = document.activeElement?.tagName?.toUpperCase() ?? "";
    if (tag === "INPUT" || tag === "TEXTAREA" || document.activeElement?.isContentEditable || tag.includes("-")) return;
    const item = Array.from(e.clipboardData.items).find(i => i.type.startsWith("image/"));
    if (item) { e.preventDefault(); handleMedgemmaFile(item.getAsFile()); }
});
medgemmaClearBtn.addEventListener("click", () => {
    medgemmaImageBase64 = null;
    medgemmaImageMime   = null;
    medgemmaFileInput.value = "";
    medgemmaPreview.classList.add("hidden");
    medgemmaDropzone.classList.remove("hidden");
});

async function callGeminiChatStream(model, systemPrompt, history, onChunk, signal) {
    const body = JSON.stringify({
        system_instruction: { parts: [{ text: systemPrompt }] },
        contents: history,
    });
    const res = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/${model}:streamGenerateContent?key=${GEMINI_API_KEY}&alt=sse`,
        { method: "POST", headers: { "Content-Type": "application/json" }, body, signal }
    );
    if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err?.error?.message || res.statusText);
    }
    const reader = res.body.getReader();
    const dec = new TextDecoder();
    let full = '';
    while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        const chunk = dec.decode(value, { stream: true });
        for (const line of chunk.split('\n')) {
            if (!line.startsWith('data: ')) continue;
            try {
                const d = JSON.parse(line.slice(6));
                const text = d?.candidates?.[0]?.content?.parts?.[0]?.text || '';
                if (text) { full += text; onChunk(full); }
            } catch {}
        }
    }
    return full;
}

async function callMedGemma(imageBase64, mimeType, prompt) {
    const model = getModel('geminiModelMedgemma');
    if (!model) throw new Error("Geen model geselecteerd. Klik ↺ naast het model-veld in Settings.");
    if (!GEMINI_API_KEY) throw new Error("Geen Gemini API key ingevuld. Vul een sleutel in bij Settings.");
    const body = JSON.stringify({
        contents: [{ parts: [
            { inline_data: { mime_type: mimeType, data: imageBase64 } },
            { text: prompt }
        ]}]
    });
    const MAX_ATTEMPTS = 3, RETRY_DELAY_MS = 3000;
    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
        const res = await fetch(
            `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${GEMINI_API_KEY}`,
            { method: "POST", headers: { "Content-Type": "application/json" }, body }
        );
        if (res.status === 503) {
            if (attempt < MAX_ATTEMPTS) {
                await new Promise(r => setTimeout(r, RETRY_DELAY_MS));
                continue;
            }
            throw new Error(`Model overbelast (503) na ${MAX_ATTEMPTS} pogingen. Probeer een ander model in Settings of wacht even.`);
        }
        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            const msg = err?.error?.message || res.statusText;
            if (res.status === 429) throw new Error(`Quotum overschreden (429). Probeer opnieuw. Details: ${msg}`);
            if (res.status === 400) throw new Error(`Ongeldige aanvraag (400): ${msg}`);
            if (res.status === 403) throw new Error(`Toegang geweigerd (403). Controleer de Gemini API-sleutel.`);
            throw new Error(`${res.status}: ${msg}`);
        }
        const data = await res.json();
        return data.candidates?.[0]?.content?.parts?.[0]?.text ?? "(geen resultaat)";
    }
}

