            function showMedgemmaResult(raw) {
                medgemmaDropzone.classList.add("hidden");
                medgemmaPreview.classList.add("hidden");
                medgemmaResultContent.innerHTML = renderMarkdown(raw);
                medgemmaResult.classList.remove("hidden");
            }

            function resetMedgemmaPanel() {
                medgemmaResult.classList.add("hidden");
                medgemmaResultContent.innerHTML = "";
                medgemmaImageBase64 = null;
                medgemmaImageMime   = null;
                medgemmaFileInput.value = "";
                medgemmaPreviewImg.src  = "";
                medgemmaPreview.classList.add("hidden");
                medgemmaDropzone.classList.remove("hidden");
            }

            medgemmaCopyBtn.addEventListener("click", () => {
                const text = medgemmaResultContent.innerText || medgemmaResultContent.textContent;
                navigator.clipboard.writeText(text).catch(() => {});
            });

            medgemmaCloseBtn.addEventListener("click", () => {
                resetMedgemmaPanel();
                if (medgemmaAccordionActive) toggleMedgemmaAccordion();
            });

            const DEFAULT_MEDGEMMA_PROMPT = `Je bent een gespecialiseerde expert radioloog. Analyseer het bijgevoegde medisch beeld en schrijf een volledig radiologisch verslag.

=== CONTEXT (uitsluitend ter referentie — niet teruggeven in de output) ===
Type onderzoek: {type_onderzoek}
Klinische inlichtingen: {klinische_inlichtingen}
Diagnostische vraagstelling: {diagnostische_vraagstelling}
Verslag protocol: {Procedure template}
=== EINDE CONTEXT ===

VERSLAGREGELS:
- Schrijf uitsluitend een VERSLAG en een BESLUIT — geen inleiding, geen uitleg, geen commentaar achteraf

- VERSLAG: gestructureerd volgens het standaard radiologisch protocol voor het opgegeven type onderzoek; indien het {Procedure template} gekend is maak je jouw verslag volgens deze opmaak, als deze niet gekend is , gebruik een beknopt standaard radiologisch verslagformaat met beknopte zinnen waarbij het gebruik van volzinnen niet noodzakelijk is en je mag met puntjes werken; zet elke bevinding op een nieuwe lijn
- BESLUIT: gerangschikt naar klinische belangrijkheid van de pathologie; beantwoord altijd expliciet de diagnostische vraagstelling indien opgegeven
- Gebruik voor opmaak uitsluitend HTML-tags: <b> voor vet, <i> voor cursief
UITVOERFORMAAT — geef UITSLUITEND dit terug, geen uitleg, geen preamble:
<b>Verslag</b>
[bevindingen, elke bevinding op een nieuwe lijn]
<b>Besluit</b>
[besluit gerangschikt naar ernst; antwoord op klinische vraag indien van toepassing]`;

