function sendToDictationFields(text) {
    if (!text) return;
    setDictationText(text);
    if (_pipDmoTa && _pipWindow && !_pipWindow.closed) {
        setNativeValue(_pipDmoTa, text);
        _pipDmoTa.style.height = 'auto';
        _pipDmoTa.style.height = _pipDmoTa.scrollHeight + 'px';
    }
}

function readDictationText() {
    let raw = "";
    // 1. Known public property names the SDK might expose
    const fromProp = clipboard.text ?? clipboard.value ?? clipboard.dictationText ?? null;
    if (fromProp) raw = fromProp;
    // 2. Cached value from input events (works when shadow DOM is open)
    else if (latestDictationText) raw = latestDictationText;
    // 3. Light DOM: textarea, text input or contenteditable
    else {
        const lightEl = clipboard.querySelector("textarea, input:not([type=submit]):not([type=button]), [contenteditable='true']");
        if (lightEl) raw = extractText(lightEl);
        // 4. Open shadow DOM
        else if (clipboard.shadowRoot) {
            const shadowEl = clipboard.shadowRoot.querySelector("textarea, input:not([type=submit]):not([type=button]), [contenteditable='true']");
            if (shadowEl) raw = extractText(shadowEl);
        }
    }
    return _normalizeDictText(raw);
}

