file.content:
const pipMedgemmaPanel = mk('div', 'rounded-lg border border-neutral-200 dark:border-slate-700 bg-white dark:bg-background overflow-hidden');
pipMedgemmaPanel.id = 'pip-medgemma-panel';
pipMedgemmaPanel.style.display = medgemmaAccordionActive ? '' : 'none';

const pmHeader = mk('div', 'flex items-center gap-2 px-3 py-2 text-sm font-medium text-neutral-900 dark:text-neutral-100 border-b border-neutral-200 dark:border-slate-700 bg-neutral-50 dark:bg-muted');
pmHeader.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/></svg> Beeldanalyse';

const pmBody = mk('div', 'px-3 py-3 space-y-2');

const pmDropzone = mk('div', 'flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-neutral-300 dark:border-slate-600 bg-neutral-50 dark:bg-muted/40 py-4 px-3 cursor-pointer hover:border-cyan-500 transition-colors text-center');
pmDropzone.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="color:#9ca3af"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg><p style="font-size:11px;color:#6b7280;margin:0">Sleep beeld hierheen of <span style="color:#0891b2;text-decoration:underline">klik om te uploaden</span><br>of plak met <kbd style="padding:1px 4px;border-radius:3px;background:#e5e7eb;font-family:monospace;font-size:10px">Ctrl+V</kbd></p>';

const pmFileInput = pipWindow.document.createElement('input');
pmFileInput.type = 'file';
pmFileInput.accept = 'image/*';
pmFileInput.style.display = 'none';
pipWindow.document.body.appendChild(pmFileInput);

const pmPreview = mk('div', 'hidden relative');
const pmImg = pipWindow.document.createElement('img');
pmImg.className = 'w-full object-contain rounded-lg border border-neutral-200 dark:border-slate-700 bg-black';
pmImg.style.maxHeight = '200px';
pmImg.alt = 'Preview';
const pmClearBtn = mk('button', 'absolute top-1 right-1 inline-flex items-center justify-center w-5 h-5 rounded-full text-white text-xs', '✕');
pmClearBtn.type = 'button';
pmClearBtn.style.cssText = 'background:rgba(30,30,30,.7)';
pmPreview.append(pmImg, pmClearBtn);

const pmAnalyseBtn = mk('button', 'w-full inline-flex items-center justify-center gap-1.5 px-3 py-1.5 text-sm font-medium rounded-md bg-cyan-600 hover:bg-cyan-700 text-white transition-colors cursor-pointer', '');
pmAnalyseBtn.type = 'button';

