input.new_string:
let medgemmaImages = []; // [{base64, mime, dataUrl}]
const medgemmaThumbnails = document.getElementById("medgemma-thumbnails");

function _addMedgemmaThumbnail(idx) {
    const img = medgemmaImages[idx];
    const wrap = document.createElement("div");
    wrap.className = "relative inline-block";
    wrap.dataset.idx = idx;
    const thumb = document.createElement("img");
    thumb.src = img.dataUrl;
    thumb.className = "w-16 h-16 object-cover rounded-md border border-neutral-200 dark:border-slate-700 bg-black";
    const rm = document.createElement("button");
    rm.type = "button";
    rm.className = "absolute -top-1 -right-1 inline-flex items-center justify-center w-4 h-4 rounded-full text-white text-xs";
    rm.style.cssText = "background:rgba(30,30,30,.75);font-size:10px;line-height:1";
    rm.textContent = "✕";
    rm.addEventListener("click", (e) => {
        e.stopPropagation();
        medgemmaImages.splice(parseInt(wrap.dataset.idx), 1);
        // Re-index remaining wrappers
        Array.from(medgemmaThumbnails.children).forEach((w, i) => { w.dataset.idx = i; });
        wrap.remove();
        if (!medgemmaImages.length) {
            medgemmaPreview.classList.add("hidden");
            medgemmaDropzone.classList.remove("hidden");
        }
    });
    wrap.append(thumb, rm);
    medgemmaThumbnails.appendChild(wrap);
}

function handleMedgemmaFile(file) {
    if (!file || !file.type.startsWith("image/")) return;
    if (file.size > 10 * 1024 * 1024) { alert("Afbeelding is groter dan 10 MB. Kies een kleinere afbeelding."); return; }
    const reader = new FileReader();
    reader.onload = (e) => {
        const dataUrl = e.target.result;
        const idx = medgemmaImages.length;
        medgemmaImages.push({ base64: dataUrl.split(",")[1], mime: file.type, dataUrl });
        _addMedgemmaThumbnail(idx);
        medgemmaPreview.classList.remove("hidden");
        medgemmaDropzone.classList.add("hidden");
    };
    reader.readAsDataURL(file);
}

medgemmaDropzone.addEventListener("click", () => medgemmaFileInput.click());
medgemmaFileInput.addEventListener("change", (e) => { Array.from(e.target.files).forEach(handleMedgemmaFile); medgemmaFileInput.value = ""; });
medgemmaDropzone.addEventListener("dragover", (e) => {
    e.preventDefault();
    medgemmaDropzone.classList.add("ring-2", "ring-cyan-500");
});
medgemmaDropzone.addEventListener("dragleave", () => {
    medgemmaDropzone.classList.remove("ring-2", "ring-cyan-500");
});
medgemmaDropzone.addEventListener("drop", (e) => {
    e.preventDefault();
    medgemmaDropzone.classList.remove("ring-2", "ring-cyan-500");
    Array.from(e.dataTransfer.files).forEach(handleMedgemmaFile);
});
document.addEventListener("paste", (e) => {
    if (medgemmaAccordion.classList.contains("hidden")) return;
    if (!medgemmaAccordion.open) return;
    // Don't intercept when a text field or web component (e.g. tiro-form-filler) is active
    const tag = document.activeElement?.tagName?.toUpperCase() ?? "";
    if (tag === "INPUT" || tag === "TEXTAREA" || document.activeElement?.isContentEditable || tag.includes("-")) return;
    const items = Array.from(e.clipboardData.items).filter(i => i.type.startsWith("image/"));
    if (items.length) { e.preventDefault(); items.forEach(i => handleMedgemmaFile(i.getAsFile())); }
});
medgemmaClearBtn.addEventListener("click", () => {
    medgemmaImages = [];
    medgemmaThumbnails.innerHTML = "";
    medgemmaPreview.classList.add("hidden");
    medgemmaDropzone.classList.remove("hidden");
});

