function handleMedgemmaFile(file) {
    if (!file || !file.type.startsWith("image/")) return;
    if (file.size > 10 * 1024 * 1024) { alert("Afbeelding is groter dan 10 MB. Kies een kleinere afbeelding."); return; }
    const reader = new FileReader();
    reader.onload = (e) => {
        const dataUrl = e.target.result;
