    medgemmaDropzone.classList.remove("ring-2", "ring-cyan-500");
});
medgemmaDropzone.addEventListener("drop", (e) => {
    e.preventDefault();
    medgemmaDropzone.classList.remove("ring-2", "ring-cyan-500");
    handleMedgemmaFile(e.dataTransfer.files[0]);
});
document.addEventListener("paste", (e) => {
    if (medgemmaAccordion.classList.contains("hidden")) return;
