input.new_string:
async function callMedGemma(images, prompt) {
    const model = getModel('geminiModelMedgemma');
    if (!model) throw new Error("Geen model geselecteerd. Klik ↺ naast het model-veld in Settings.");
    if (!GEMINI_API_KEY) throw new Error("Geen Gemini API key ingevuld. Vul een sleutel in bij Settings.");
    const imageParts = images.map(img => ({ inline_data: { mime_type: img.mime, data: img.base64 } }));
    const body = JSON.stringify({
        contents: [{ parts: [...imageParts, { text: prompt }] }]
    });

input.old_string:
async function callMedGemma(imageBase64, mimeType, prompt) {
    const model = getModel('geminiModelMedgemma');
    if (!model) throw new Error("Geen model geselecteerd. Klik ↺ naast het model-veld in Settings.");
    if (!GEMINI_API_KEY) throw new Error("Geen Gemini API key ingevuld. Vul een sleutel in bij Settings.");
    const body = JSON.stringify({
        contents: [{ parts: [
            { inline_data: { mime_type: mimeType, data: imageBase64 } },
            { text: prompt }
        ]}]
    });

