input.new_string:
const pmPreview = mk('div', 'hidden');
const pmThumbnails = mk('div', 'flex flex-wrap gap-1.5');
const pmClearBtn = mk('button', 'mt-1.5 inline-flex items-center gap-1 px-2 py-0.5 text-xs rounded-md cursor-pointer transition-colors', '✕ Alles wissen');
pmClearBtn.type = 'button';
pmClearBtn.style.cssText = 'border:1px solid #d1d5db;background:#fff;color:#6b7280;font-size:10px';
pmPreview.append(pmThumbnails, pmClearBtn);

function _addPipMedgemmaThumbnail(idx) {
    const img = medgemmaImages[idx];
    const wrap = pipWindow.document.createElement('div');
    wrap.style.cssText = 'position:relative;display:inline-block';
    wrap.dataset.idx = idx;
    const thumb = pipWindow.document.createElement('img');
    thumb.src = img.dataUrl;
    thumb.style.cssText = 'width:56px;height:56px;object-fit:cover;border-radius:6px;border:1px solid #e5e7eb;background:#000';
    const rm = pipWindow.document.createElement('button');
    rm.type = 'button';
    rm.textContent = '✕';
    rm.style.cssText = 'position:absolute;top:-4px;right:-4px;width:14px;height:14px;border-radius:50%;background:rgba(30,30,30,.75);color:#fff;font-size:9px;display:inline-flex;align-items:center;justify-content:center;border:none;cursor:pointer;line-height:1;padding:0';
    rm.addEventListener('click', (e) => {
        e.stopPropagation();
        medgemmaImages.splice(parseInt(wrap.dataset.idx), 1);
        Array.from(pmThumbnails.children).forEach((w, i) => { w.dataset.idx = i; });
        wrap.remove();
        if (!medgemmaImages.length) {
            pmPreview.classList.add('hidden');
            pmDropzone.classList.remove('hidden');
        }
    });
    wrap.append(thumb, rm);
    pmThumbnails.appendChild(wrap);
}

