// File handling for PiP MedGemma panel — updates shared medgemmaImageBase64/Mime
function handlePipMedgemmaFile(file) {
    if (!file || !file.type.startsWith('image/')) return;
    if (file.size > 10 * 1024 * 1024) { pipWindow.alert('Afbeelding is groter dan 10 MB.'); return; }
    const reader = new pipWindow.FileReader();
    reader.onload = (e) => {
        const dataUrl = e.target.result;
        medgemmaImageBase64 = dataUrl.split(',')[1];
        medgemmaImageMime   = file.type;
        pmImg.src = dataUrl;
        pmPreview.classList.remove('hidden');
        pmDropzone.classList.add('hidden');
    };
    reader.readAsDataURL(file);
}

pmDropzone.addEventListener('click', () => pmFileInput.click());
pmFileInput.addEventListener('change', (e) => handlePipMedgemmaFile(e.target.files[0]));
pmDropzone.addEventListener('dragover', (e) => { e.preventDefault(); pmDropzone.style.outline = '2px solid #06b6d4'; });
pmDropzone.addEventListener('dragleave', () => { pmDropzone.style.outline = ''; });
pmDropzone.addEventListener('drop', (e) => { e.preventDefault(); pmDropzone.style.outline = ''; handlePipMedgemmaFile(e.dataTransfer.files[0]); });
pipWindow.document.addEventListener('paste', (e) => {
    if (pipMedgemmaPanel.style.display === 'none') return;
    const item = Array.from(e.clipboardData.items).find(i => i.type.startsWith('image/'));
    if (item) { e.preventDefault(); handlePipMedgemmaFile(item.getAsFile()); }
});
pmClearBtn.addEventListener('click', () => {
    medgemmaImageBase64 = null;
    medgemmaImageMime   = null;
    pmFileInput.value   = '';
    pmImg.src           = '';
    pmPreview.classList.add('hidden');
    pmDropzone.classList.remove('hidden');
});
pmCopyResultBtn.addEventListener('click', () => {
    const text = pmResultContent.innerText || pmResultContent.textContent;
    navigator.clipboard.writeText(text).catch(() => {});
});

pmCloseResultBtn.addEventListener('click', () => {
    pmResult.classList.add('hidden');
    pmResultContent.innerHTML = '';
    medgemmaImageBase64 = null;
    medgemmaImageMime   = null;
    pmFileInput.value   = '';
    pmImg.src           = '';
    pmPreview.classList.add('hidden');
    pmDropzone.classList.remove('hidden');
    if (medgemmaAccordionActive) toggleMedgemmaAccordion();
});

