function setDictationText(text) {
    // Try light DOM first, then shadow DOM
    const el = clipboard.querySelector("textarea, input:not([type=submit])..., [contenteditable='true']")
        || clipboard.shadowRoot?.querySelector(...);
    if (el) {
        if ("value" in el) {
