function extractAnyField(...searchTerms) {
    return extractClinicalField(latestClinicalResponse, ...searchTerms)
        || extractClinicalField(latestContextResponse, ...searchTerms)
        || _extractPacsParam(searchTerms);
}

function _extractPacsParam(searchTerms) {
    const map = [
        [pacsTypeOnderzoek,             ["type onderzoek", "type of examination", "onderzoek"]],
        [pacsLateralisatie,              ["lateralisatie", "laterality", "lateralisation"]],
        [pacsKlinischeInlichtingen,      ["klinische inlichtingen", "clinical information", "klinisch"]],
        [pacsDiagnostischeVraagstelling, ["diagnostische vraagstelling", "diagnostische vraag", "diagnostic question"]],
    ];
    for (const [val, keys] of map) {
        if (!val) continue;
        if (searchTerms.some(t => keys.some(k => k.includes(t.toLowerCase()) || t.toLowerCase().includes(k)))) {
            return val;
        }
    }
    return "";

