let _multiStudies = [];

function _getStudyLabel() {
    const type = extractAnyField("type onderzoek", "type of examination", "onderzoek") || '';
    const lat  = extractAnyField("lateralisatie", "laterality") || '';
    return [type, lat].filter(Boolean).join(' ').toUpperCase().trim();
}

async function _runAutofillSilent(tekst, context) {
    const logic = window._flowTextTemplateLogic || localStorage.getItem('textTemplateLogic') || '';
    const backupTemplate = localStorage.getItem('autofillBackupUrl') || DEFAULT_AUTOFILL_BACKUP_PROMPT;
    const prompt = fillPrompt(backupTemplate, {
        tekst,
        type_onderzoek: context.typeOnderzoek,
        klinische_inlichtingen: context.ki,
        diagnostische_vraagstelling: context.dv,
        text_template: context.textTemplate,
        text_template_logic: logic,
    });
    let result = '';
    await callGeminiStream(getModel('geminiModelAutofillBackup'), prompt, (partial) => { result = partial; });
    if (vcAfterAutofillEnabled) {
        const vcTemplate = verslagCheckUrlInput.value.trim() || DEFAULT_VERSLAG_CHECK_PROMPT;
        const vcPrompt = fillPrompt(vcTemplate, {
            tekst: result,
            type_onderzoek: context.typeOnderzoek,
            klinische_inlichtingen: context.ki,
            diagnostische_vraagstelling: context.dv,
            patient_info: extractPatientInfo(),
            text_template: context.textTemplate || '',
        });
        await callGeminiStream(getModel('geminiModelVerslag'), vcPrompt, (partial) => { result = partial; });
    }
    return result;
}

function _clearStudyFields() {
    setDictationText('');
    if (_pipWindow && !_pipWindow.closed && _pipDmoTa) {
        setNativeValue(_pipDmoTa, '');
        try { _pipDmoTa.style.height = 'auto'; } catch (_) {}
    }
    _autoStudyLastDetected = '';
    if (contextForm) {
        deepFillByLabel(contextForm, "type onderzoek", "");
        deepClearSelectByLabel(contextForm, "lateralisatie");
        deepFillByLabel(contextForm, "klinische inlichtingen", "");
        deepFillByLabel(contextForm, "diagnostische vraagstelling", "");
    }
}

function _updateVoegToeBtns() {
    const n = _multiStudies.length;
    const lbl = n > 0 ? `Voeg toe (${n})` : 'Voeg toe';
    const btn = document.getElementById('voeg-toe-btn');
    if (btn) btn.textContent = lbl;
    if (_pipWindow && !_pipWindow.closed) {
        const pbtn = _pipWindow.document.getElementById('pip-voeg-toe-btn');
        if (pbtn) pbtn.textContent = lbl;
    }
}

async function _voegToeHandler(dictText) {
    const label = _getStudyLabel();
    const tekst = dictText || readDictationText().trim();
    if (!tekst) { alert('Geen dictatietekst. Dicteer eerst een verslag.'); return; }
    const context = {
        typeOnderzoek: extractAnyField("type onderzoek", "type of examination", "onderzoek"),
        ki:  extractAnyField("klinische inlichtingen", "clinical information", "klinisch"),
        dv:  extractAnyField("diagnostische vraagstelling", "diagnostische vraag", "diagnostic question"),
        textTemplate: window._flowTextTemplate || window._flowUserTextTemplate || '',
    };
    const originalWithHeader = _prependTtHeader(tekst);
    const btn    = document.getElementById('voeg-toe-btn');
    const pipBtn = _pipWindow?.document?.getElementById('pip-voeg-toe-btn');
    if (btn)    { btn.disabled = true;    btn.textContent = 'Bezig…'; }
    if (pipBtn) { pipBtn.disabled = true;  pipBtn.textContent = 'Bezig…'; }
    let autofillResult = null;
    try {
        if (GEMINI_API_KEY) autofillResult = await _runAutofillSilent(tekst, context);
    } catch (e) {
        const retry = confirm('Autofill mislukt: ' + e.message + '\n\nOpnieuw proberen?');
        if (retry) {
            try { autofillResult = await _runAutofillSilent(tekst, context); } catch (_) {}
        }
    }
    const autofillWithHeader = autofillResult ? _prependTtHeader(autofillResult) : null;
    _multiStudies.push({ label, originalWithHeader, autofillWithHeader: autofillWithHeader || originalWithHeader, showingOriginal: false });
    _clearStudyFields();
    if (btn)    { btn.disabled = false; btn.style.color = '#16a34a'; setTimeout(() => { btn.style.color = ''; }, 1500); }
    if (pipBtn) { pipBtn.disabled = false; pipBtn.style.color = '#16a34a'; setTimeout(() => { pipBtn.style.color = ''; }, 1500); }
    _updateVoegToeBtns();
}

