function _pipReset() {
    _pipRealtimeAbort?.abort();
    if (typeof _vcAbort !== 'undefined') _vcAbort?.abort();
    clearTimeout(_pipRealtimeDebounce);
    _pipRealtimeLastText = '';
    // dicteervelden leegmaken (textarea + contenteditable)
    ta.value = '';
    setNativeValue(ta, '');
    _autoGrow();
    ce.innerHTML = '';
    const _d = pipWindow.document.createElement('div');
    _d.innerHTML = '<br>';
    ce.appendChild(_d);
    setDictationText('');
    // Reset auto-detectie + wis form-velden zodat bij nieuwe patiënt een nieuw onderzoekstype herkend kan worden
    if (autoStudyDetect) {
        _autoStudyLastDetected = '';
        if (contextForm) {
            deepFillByLabel(contextForm, "type onderzoek", "");
            deepClearSelectByLabel(contextForm, "lateralisatie");
        }
    }
    // resultaatpanelen verbergen
    trPanel.style.display = 'none';
    rtPanel.style.display = 'none';
    vcPanel.style.display = 'none';
    pipTtPanel.style.display = 'none';
    sentInd.classList.add('hidden');
    sentInd.classList.remove('inline-flex');
}

