// 2-second debounce on textarea input:
//   - always sync text to PSK dictation field
//   - only run realtime verslag check when realtimeEnabled
ta.addEventListener('input', () => {
    if (_pipInlineMode) return;
    clearTimeout(_pipRealtimeDebounce);
    _pipRealtimeDebounce = setTimeout(async () => {
        const tekst = ta.value.trim();
        if (!tekst || tekst === _pipRealtimeLastText) return;
        _pipRealtimeLastText = tekst;

        // Keep latestDictationText in sync for autofill/translate/verslag check.
        setDictationText(tekst);
        _scheduleCalcScan();

        // Only run realtime check when the toggle is on
        if (!realtimeEnabled) return;
        // Only check when the last non-empty line ends with sentence-ending punctuation
        const lastLine = tekst.split('\n').map(l => l.trim()).filter(Boolean).pop();
        if (!lastLine || !/[.!?]$/.test(lastLine)) return;

        _pipRealtimeAbort?.abort();
        _pipRealtimeAbort = new AbortController();
        rtPanel.style.display = '';
        rtStatus.innerHTML = '<span class="ai-spinner"></span> Verwerken…';
        rtActions.style.display = 'none';
        rtOrigBtn.style.display = 'none';
        _rtOrigText = tekst;
        _rtShowingOrig = false;
        _rtResultHTML = null;
        rtOrigBtn.textContent = '↩ Origineel';
        _rtCorrText = null;

        const template = verslagCheckUrlInput.value.trim() || DEFAULT_VERSLAG_CHECK_PROMPT;
        const typeOnderzoek = extractAnyField('type onderzoek', 'type of examination', 'onderzoek');
        const ki  = extractAnyField('klinische inlichtingen', 'clinical information', 'klinisch');
        const dv  = extractAnyField('diagnostische vraagstelling', 'diagnostische vraag', 'diagnostic question');
        const pat = extractPatientInfo();
        const prompt = fillPrompt(template, { tekst, type_onderzoek: typeOnderzoek, klinische_inlichtingen: ki, diagnostische_vraagstelling: dv, patient_info: pat });

        if (!GEMINI_API_KEY) { rtStatus.textContent = 'Geen API-sleutel ingesteld.'; return; }
        try {
            let first = true;
            let pipStreamedText = '';
            await callGeminiStream(getModel('geminiModelRealtime'), prompt, (partial) => {
                if (first) { rtContent.innerHTML = ''; first = false; }
                pipStreamedText = partial;
                rtContent.innerHTML = partial.replace(/\n/g, '<br>');

