const btnFontUp   = mk('button', SZ, 'A+'); btnFontUp.type   = 'button';
btnFontDown.style.fontSize = '11px';
btnFontUp.style.fontSize   = '13px';
btnFontDown.addEventListener('click', () => { _pipZoom = Math.max(0.5, +(_pipZoom - 0.1).toFixed(1)); _applyZoom(); });
btnFontUp.addEventListener('click',   () => { _pipZoom = Math.min(2.0, +(_pipZoom + 0.1).toFixed(1)); _applyZoom(); });

const VC_BTN_OFF = SZ.replace('font-bold leading-none', '');
const VC_BTN_ON  = 'inline-flex items-center justify-center w-7 h-7 rounded-md border border-green-500 bg-green-500 hover:bg-green-600 text-white transition-colors cursor-pointer';
const btnPipVc = mk('button', realtimeEnabled ? VC_BTN_ON : VC_BTN_OFF, '');
btnPipVc.type = 'button';
btnPipVc.title = 'Verslag check';
btnPipVc.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>';

// Sync colour with realtime toggle
realtimeToggle.addEventListener('click', () => {
    btnPipVc.className = realtimeEnabled ? VC_BTN_ON : VC_BTN_OFF;
});

btnPipVc.addEventListener('click', async () => {
    const tekst = (_pipInlineMode ? getCeText() : ta.value).trim();
    if (!tekst) { pipWindow.alert('Geen dictatietekst. Dicteer eerst een verslag.'); return; }
    if (!GEMINI_API_KEY) { pipWindow.alert('Geen Gemini API-sleutel ingesteld in Settings.'); return; }

    _vcAbort?.abort();
    _vcAbort = new AbortController();
    btnPipVc.className = VC_BTN_ON; // groen tijdens uitvoering
    vcPanel.style.display = '';
    vcContent.innerHTML = '';
    vcStatus.textContent = 'Verwerken…';
    vcActions.style.display = 'none';
    vcOrigBtn.style.display = 'none';
    _vcOrigText = tekst;
    _vcShowingOrig = false;
    _vcResultHTML = null;
    vcOrigBtn.textContent = '↩ Origineel';

    const template = verslagCheckUrlInput.value.trim() || DEFAULT_VERSLAG_CHECK_PROMPT;
    const typeOnderzoek = extractAnyField('type onderzoek', 'type of examination', 'onderzoek');
    const ki  = extractAnyField('klinische inlichtingen', 'clinical information', 'klinisch');
    const dv  = extractAnyField('diagnostische vraagstelling', 'diagnostische vraag', 'diagnostic question');
    const pat = extractPatientInfo();
    const prompt = fillPrompt(template, { tekst, type_onderzoek: typeOnderzoek, klinische_inlichtingen: ki, diagnostische_vraagstelling: dv, patient_info: pat, text_template: window._flowTextTemplate || '' });

    try {
        let streamedText = '';
        let first = true;
        await callGeminiStream(getModel('geminiModelVerslag'), prompt, (partial) => {
            if (first) { vcContent.innerHTML = ''; first = false; }
            streamedText = partial;
            vcContent.innerHTML = partial.replace(/\n/g, '<br>');
            vcStatus.textContent = '';
        }, _vcAbort.signal);
        const corrected = extractCleanCorrection(streamedText);
        vcContent.innerHTML = computeDiffHTMLStructured(tekst, corrected);
        vcActions.style.display = 'flex';
        vcOrigBtn.style.display = _vcOrigText ? '' : 'none';
    } catch (e) {
        if (e.name !== 'AbortError') vcStatus.textContent = 'Fout: ' + e.message;
    } finally {
        // Restore: groen als realtime aan, grijs als uit
        btnPipVc.className = realtimeEnabled ? VC_BTN_ON : VC_BTN_OFF;
    }
});

const btnPipCalc = mk('button', 'inline-flex items-center justify-center w-7 h-7 rounded-md border border-cyan-300 dark:border-cyan-800 bg-white dark:bg-muted hover:bg-neutral-200 dark:hover:bg-slate-600 transition-colors cursor-pointer', '🧮');
btnPipCalc.type = 'button';
btnPipCalc.title = 'Calculator';
fontBtns.append(btnPipAI, btnPipVc, btnPipCalc, btnPipCam, btnFontDown, btnFontUp);
