const doc = isMain ? document : (_pipWindow?.document || document);
const lastResultEl = isMain ? ttContent : (_pipTtRef?.content || null);
const targetActions = isMain ? ttActions : (_pipTtRef?.actions || null);

// Build / populate the container of previous studies
if (isMain) {
    const msp = document.getElementById('multi-study-result');
    if (!msp) return;
    msp.innerHTML = '';
    msp.classList.remove('hidden');
    // Header
    const mspHead = document.createElement('div');
    mspHead.className = 'flex items-center justify-between px-3 py-1.5 bg-cyan-50 dark:bg-cyan-900/10 border-b border-cyan-100 dark:border-cyan-900/30';
    const mspTitle = document.createElement('span');
    mspTitle.className = 'text-xs font-medium text-cyan-700 dark:text-cyan-400';
    mspTitle.textContent = `Multi-studie — ${_multiStudies.length + 1} onderzoeken`;
    const mspClose = document.createElement('button');
    mspClose.type = 'button';
    mspClose.className = 'text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 leading-none cursor-pointer text-base';
    mspClose.title = 'Sluiten (bewaar studies voor hergebruik)';
    mspClose.textContent = '×';
    mspClose.addEventListener('click', () => {
        msp.classList.add('hidden');
        ttResultPanel.classList.add('hidden');
        document.querySelectorAll('.ms-extra-btn').forEach(b => b.remove());
        showTemplatePreview();
    });
    mspHead.append(mspTitle, mspClose);
    msp.appendChild(mspHead);
    const studyWrap = document.createElement('div');
    _multiStudies.forEach((s, i) => studyWrap.appendChild(_buildMsPanel(s, i, document)));
    msp.appendChild(studyWrap);
} else {
    if (!_pipWindow || _pipWindow.closed) return;
    const pipMsp = _pipWindow.document.getElementById('pip-multi-study-result');
    if (!pipMsp) return;
    pipMsp.innerHTML = '';
    pipMsp.style.display = '';
    // Header
    const mspHead = _pipWindow.document.createElement('div');
    mspHead.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:6px 12px;background:#ecfdf5;border-bottom:1px solid #a7f3d0';
    const mspTitle = _pipWindow.document.createElement('span');
    mspTitle.style.cssText = 'font-size:11px;font-weight:500;color:#065f46';
    mspTitle.textContent = `Multi-studie — ${_multiStudies.length + 1} onderzoeken`;
    const mspClose = _pipWindow.document.createElement('button');
    mspClose.type = 'button';
    mspClose.style.cssText = 'font-size:16px;line-height:1;color:#9ca3af;cursor:pointer;background:none;border:none;padding:0';
    mspClose.title = 'Sluiten (bewaar studies)';
    mspClose.textContent = '×';
    mspClose.addEventListener('click', () => {
        pipMsp.style.display = 'none';
        if (_pipTtRef?.panel) _pipTtRef.panel.style.display = 'none';
        if (_pipTtRef?.actions) _pipTtRef.actions.querySelectorAll('.ms-extra-btn').forEach(b => b.remove());
    });
    mspHead.append(mspTitle, mspClose);
    pipMsp.appendChild(mspHead);
    _multiStudies.forEach((s, i) => pipMsp.appendChild(_buildMsPanel(s, i, _pipWindow.document)));
}

