async function runAutofillBackup(pipRefs, providedText) {
    const tekst = providedText || readDictationText() || _realtimeOriginalText || '';
    if (!tekst) {
        if (pipRefs) pipRefs.pipAlert('Geen dictatietekst gevonden. Dicteer eerst uw bevindingen.');
        else alert("Geen dictatietekst gevonden. Dicteer eerst uw bevindingen.");
        return;
    }
    const typeOnderzoek = extractAnyField("type onderzoek", "type of examination", "onderzoek");
    const ki  = extractAnyField("klinische inlichtingen", "clinical information", "klinisch");
    const dv  = extractAnyField("diagnostische vraagstelling", "diagnostische vraag", "diagnostic question");
    const logic = window._flowTextTemplateLogic || localStorage.getItem('textTemplateLogic') || '';
    const savedPrompt = localStorage.getItem('autofillBackupUrl');
    const backupTemplate = savedPrompt || DEFAULT_AUTOFILL_BACKUP_PROMPT;
    const backupPrompt = fillPrompt(backupTemplate, {
        tekst,
        type_onderzoek: typeOnderzoek,
        klinische_inlichtingen: ki,
        diagnostische_vraagstelling: dv,
        text_template: window._flowTextTemplate || window._flowUserTextTemplate,
        text_template_logic: logic,
    });
    if (!GEMINI_API_KEY) {
        if (pipRefs) {
            pipRefs.panel.style.display = '';
            pipRefs.status.innerHTML = '';
            pipRefs.content.innerHTML = noApiKeyHtml(backupPrompt);
            pipRefs.actions.style.display = 'none';
        } else {
            hideTemplatePreview();
            ttResultPanel.classList.remove('hidden');
            ttStatus.innerHTML = '';
            ttContent.innerHTML = noApiKeyHtml(backupPrompt);
            ttActions.style.display = 'none';
        }
        return;
    }

    // Resolve target elements (main page or PiP)
    const isMain = !pipRefs;
    const targetContent = isMain ? ttContent : pipRefs.content;
    const targetStatus  = isMain ? ttStatus  : pipRefs.status;
    const targetActions = isMain ? ttActions : pipRefs.actions;
    const targetToggle  = isMain ? ttToggleOrig : pipRefs.toggle;

    // Close realtime panel
    if (isMain) {
        _realtimeAbort?.abort();
        realtimePanel.classList.add('hidden');
    } else {
        _pipRealtimeAbort?.abort();
        clearTimeout(_pipRealtimeDebounce);
        if (pipRefs.rtPanel) pipRefs.rtPanel.style.display = 'none';
    }

    // Show result panel (hide template preview first)
    if (isMain) {
        document.getElementById('text-template-accordion').setAttribute('open', '');
        hideTemplatePreview();
        ttResultPanel.classList.remove('hidden');
        _ttOriginalText = null;
        _ttShowingOrig = false;
        _ttResultHTML = null;
    } else {
        pipRefs.panel.style.display = '';
        pipRefs.origText = null;
        pipRefs.showingOrig = false;
        pipRefs.resultHTML = null;
    }

    targetActions.style.display = 'none';
    targetToggle.style.display = 'none';
    targetToggle.textContent = 'Toon origineel';
    targetStatus.innerHTML = '<span class="autofill-spinner"></span> Verwerken…';
    targetContent.innerHTML = '';

    _ttAbort?.abort();
    _ttAbort = new AbortController();

    let firstChunk = true;
    try {
        // Phase 1: generate filled backup template
        await callGeminiStream(getModel('geminiModelAutofillBackup'), backupPrompt, (partial) => {
            if (firstChunk) { firstChunk = false; targetStatus.innerHTML = ''; }
            targetContent.innerHTML = renderMarkdown(partial);
        }, _ttAbort.signal);

        // Save the backup result for the toggle (↩ Ingevuld)
        const backupPlainText = targetContent.innerText;
        if (isMain) _ttOriginalText = backupPlainText;
