async function callGeminiStream(model, prompt, onChunk, signal) {
    const fullPrompt = GEMINI_SYSTEM + "\n\n" + prompt;
    const body = { contents: [{ parts: [{ text: fullPrompt }] }] };
    const res = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/${model}:streamGenerateContent?key=${GEMINI_API_KEY}&alt=sse`,
        { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body), signal }
    );
    if (!res.ok) {
        const b = await res.json().catch(() => ({}));
        const msg = b?.error?.message || res.statusText;
        if (res.status === 429) throw new Error(`Quotum overschreden (429). Probeer een ander model in Settings. Details: ${msg}`);
        if (res.status === 400) throw new Error(`Ongeldige aanvraag (400): ${msg}`);
        if (res.status === 403) throw new Error(`Toegang geweigerd (403). Controleer de API-sleutel via aistudio.google.com/apikey.`);
        throw new Error(`Gemini fout ${res.status}: ${msg}`);
    }
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "", fullText = "";
    while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
