    const sep = doc.createElement('span');
    sep.className = 'ms-extra-btn flex-1';
    if (!isMain) sep.style.cssText = 'flex:1';
    targetActions.appendChild(sep);

    const copyAllBtn = doc.createElement('button');
    copyAllBtn.type = 'button';
    copyAllBtn.className = 'ms-extra-btn' + (isMain ? ' px-3 py-1.5 text-xs font-medium rounded-md border border-neutral-300 dark:border-slate-700 bg-white dark:bg-muted hover:bg-neutral-100 dark:hover:bg-accent text-neutral-700 dark:text-neutral-200 transition-colors' : '');
    if (!isMain) copyAllBtn.style.cssText = 'border:1px solid #d1d5db;background:#fff;color:#374151;font-size:11px;padding:4px 10px;border-radius:6px;cursor:pointer';
    copyAllBtn.textContent = 'Kopieer alles';
    copyAllBtn.addEventListener('click', () => {
        const mspEl = isMain ? document.getElementById('multi-study-result') : (_pipWindow?.document?.getElementById('pip-multi-study-result'));
        const allTxt = _getAllStudiesText(mspEl, lastResultEl);
        navigator.clipboard.writeText(allTxt).catch(() => {});
        _resetMultiStudies();
        if (isMain) { ttResultPanel.classList.add('hidden'); showTemplatePreview(); }
        else if (_pipTtRef?.panel) _pipTtRef.panel.style.display = 'none';
    });
    targetActions.appendChild(copyAllBtn);

    const sendAllBtn = doc.createElement('button');
    sendAllBtn.type = 'button';
    sendAllBtn.title = 'Stuur alles naar dictatie';
    sendAllBtn.className = 'ms-extra-btn' + (isMain ? ' inline-flex items-center justify-center w-[30px] h-[30px] rounded-md border border-neutral-300 dark:border-slate-700 bg-white dark:bg-muted hover:bg-neutral-100 dark:hover:bg-accent text-neutral-700 dark:text-neutral-200 transition-colors' : '');
    if (!isMain) sendAllBtn.style.cssText = 'width:28px;height:28px;display:inline-flex;align-items:center;justify-content:center;border:1px solid #d1d5db;background:#fff;color:#374151;border-radius:6px;cursor:pointer';
    sendAllBtn.innerHTML = doubleArrowSvg;
    sendAllBtn.addEventListener('click', () => {
        const mspEl = isMain ? document.getElementById('multi-study-result') : (_pipWindow?.document?.getElementById('pip-multi-study-result'));
        const allTxt = _getAllStudiesText(mspEl, lastResultEl);
        if (isMain) {
            sendToDictationFields(allTxt);
        } else {
            if (_pipDmoTa) { setNativeValue(_pipDmoTa, allTxt); try { _pipDmoTa.style.height = 'auto'; _pipDmoTa.style.height = _pipDmoTa.scrollHeight + 'px'; } catch (_) {} }
            setDictationText(allTxt);
        }
        _resetMultiStudies();
        if (isMain) { ttResultPanel.classList.add('hidden'); showTemplatePreview(); }
        else if (_pipTtRef?.panel) _pipTtRef.panel.style.display = 'none';
    });
    targetActions.appendChild(sendAllBtn);
}

